 35→static void viewport_handle_set_source(struct wl_client *client,
 36→		struct wl_resource *resource, wl_fixed_t x_fixed, wl_fixed_t y_fixed,
 37→		wl_fixed_t width_fixed, wl_fixed_t height_fixed) {
 38→	struct wlr_viewport *viewport = viewport_from_resource(resource);
 39→	if (viewport == NULL) {
 40→		wl_resource_post_error(resource, WP_VIEWPORT_ERROR_NO_SURFACE,
 41→			"wp_viewport.set_source sent after wl_surface has been destroyed");
 42→		return;
 43→	}
 44→
 45→	struct wlr_surface_state *pending = &viewport->surface->pending;
 46→
 47→	double x = wl_fixed_to_double(x_fixed);
 48→	double y = wl_fixed_to_double(y_fixed);
 49→	double width = wl_fixed_to_double(width_fixed);
 50→	double height = wl_fixed_to_double(height_fixed);
 51→
 52→	if (x == -1.0 && y == -1.0 && width == -1.0 && height == -1.0) {
 53→		pending->viewport.has_src = false;
 54→	} else if (x < 0 || y < 0 || width <= 0 || height <= 0) {
 55→		wl_resource_post_error(resource, WP_VIEWPORT_ERROR_BAD_VALUE,
 56→			"wl_viewport.set_source sent with invalid values");
 57→		return;
 58→	} else {
 59→		pending->viewport.has_src = true;
 60→	}
 61→
 62→	pending->viewport.src.x = x;
 63→	pending->viewport.src.y = y;
 64→	pending->viewport.src.width = width;
 65→	pending->viewport.src.height = height;
 66→
 67→	pending->committed |= WLR_SURFACE_STATE_VIEWPORT;
 68→}
