 70→static void viewport_handle_set_destination(struct wl_client *client,
 71→		struct wl_resource *resource, int32_t width, int32_t height) {
 72→	struct wlr_viewport *viewport = viewport_from_resource(resource);
 73→	if (viewport == NULL) {
 74→		wl_resource_post_error(resource, WP_VIEWPORT_ERROR_NO_SURFACE,
 75→			"wp_viewport.set_destination sent after wl_surface has been destroyed");
 76→		return;
 77→	}
 78→
 79→	struct wlr_surface_state *pending = &viewport->surface->pending;
 80→
 81→	if (width == -1 && height == -1) {
 82→		pending->viewport.has_dst = false;
 83→	} else if (width <= 0 || height <= 0) {
 84→		wl_resource_post_error(resource, WP_VIEWPORT_ERROR_BAD_VALUE,
 85→			"wl_viewport.set_destination sent with invalid values");
 86→		return;
 87→	} else {
 88→		pending->viewport.has_dst = true;
 89→	}
 90→
 91→	pending->viewport.dst_width = width;
 92→	pending->viewport.dst_height = height;
 93→
 94→	pending->committed |= WLR_SURFACE_STATE_VIEWPORT;
 95→}
