135→static bool check_src_buffer_bounds(const struct wlr_surface_state *state) {
136→	int width = state->buffer_width / state->scale;
137→	int height = state->buffer_height / state->scale;
138→	wlr_output_transform_coords(state->transform, &width, &height);
139→
140→	struct wlr_fbox box = state->viewport.src;
141→	return box.x + box.width <= width && box.y + box.height <= height;
142→}
