144→static void viewport_handle_surface_client_commit(struct wl_listener *listener,
145→		void *data) {
146→	struct wlr_viewport *viewport =
147→		wl_container_of(listener, viewport, surface_client_commit);
148→
149→	struct wlr_surface_state *state = &viewport->surface->pending;
150→
151→	if (!state->viewport.has_dst &&
152→			(floor(state->viewport.src.width) != state->viewport.src.width ||
153→			floor(state->viewport.src.height) != state->viewport.src.height)) {
154→		wlr_surface_reject_pending(viewport->surface,
155→			viewport->resource, WP_VIEWPORT_ERROR_BAD_SIZE,
156→			"wl_viewport.set_source width and height must be integers "
157→			"when the destination rectangle is unset");
158→		return;
159→	}
160→
161→	if (state->viewport.has_src && wlr_surface_state_has_buffer(state) &&
162→			!check_src_buffer_bounds(state)) {
163→		wlr_surface_reject_pending(viewport->surface,
164→			viewport->resource, WP_VIEWPORT_ERROR_OUT_OF_BUFFER,
165→			"source rectangle out of buffer bounds");
166→		return;
167→	}
168→}
