175→static void viewporter_handle_get_viewport(struct wl_client *client,
176→		struct wl_resource *resource, uint32_t id,
177→		struct wl_resource *surface_resource) {
178→	struct wlr_surface *surface = wlr_surface_from_resource(surface_resource);
179→
180→	if (wlr_addon_find(&surface->addons, NULL, &surface_addon_impl) != NULL) {
181→		wl_resource_post_error(resource, WP_VIEWPORTER_ERROR_VIEWPORT_EXISTS,
182→			"wp_viewport for this surface already exists");
183→		return;
184→	}
185→
186→	struct wlr_viewport *viewport = calloc(1, sizeof(*viewport));
187→	if (viewport == NULL) {
188→		wl_client_post_no_memory(client);
189→		return;
190→	}
191→
192→	uint32_t version = wl_resource_get_version(resource);
193→	viewport->resource = wl_resource_create(client, &wp_viewport_interface,
194→		version, id);
195→	if (viewport->resource == NULL) {
196→		wl_client_post_no_memory(client);
197→		free(viewport);
198→		return;
199→	}
200→	wl_resource_set_implementation(viewport->resource, &viewport_impl,
201→		viewport, viewport_handle_resource_destroy);
202→
203→	viewport->surface = surface;
204→
205→	wlr_addon_init(&viewport->addon, &surface->addons, NULL, &surface_addon_impl);
206→
207→	viewport->surface_client_commit.notify = viewport_handle_surface_client_commit;
208→	wl_signal_add(&surface->events.client_commit, &viewport->surface_client_commit);
209→}
