 81→// This is used for wlr_scene where it unconditionally locks buffers preventing
 82→// reuse of the existing texture for shm clients. With the usage pattern of
 83→// wlr_scene surface handling, we can mark its locked buffer as safe
 84→// for mutation.
 85→static void client_buffer_mark_next_can_damage(struct wlr_client_buffer *buffer) {
 86→	buffer->n_ignore_locks++;
