 89→static void scene_buffer_unmark_client_buffer(struct wlr_scene_buffer *scene_buffer) {
 90→	if (!scene_buffer->buffer) {
 91→		return;
 92→	}
 93→
 94→	struct wlr_client_buffer *buffer = wlr_client_buffer_get(scene_buffer->buffer);
 95→	if (!buffer) {
 96→		return;
 97→	}
 98→
 99→	// If the buffer was a single-pixel buffer where we cached its color
100→	// then it won't have been marked as damage-allowed.
101→	if (buffer->n_ignore_locks > 0) {
102→		buffer->n_ignore_locks--;
103→	}
104→}
