2619→                 dx = dy * max + 0.5;
2620→                 geometry.width  = (int)(dx + real_basew);
2621→                 geometry.height = (int)(dy + real_baseh);
2622→             }
2623→         }
2624→    }
2625→
2626→    /* Handle the minimum size */
2627→    geometry.width = MAX(geometry.width, minw);
2628→    geometry.height = MAX(geometry.height, minh);
2629→
2630→    /* Handle the maximum size */
2631→    if(c->size_hints.flags & XCB_ICCCM_SIZE_HINT_P_MAX_SIZE)
2632→    {
2633→        if(c->size_hints.max_width)
2634→            geometry.width = MIN(geometry.width, c->size_hints.max_width);
2635→        if(c->size_hints.max_height)
2636→            geometry.height = MIN(geometry.height, c->size_hints.max_height);
2637→    }
2638→
2639→    /* Handle the size increment */
2640→    if(c->size_hints.flags & (XCB_ICCCM_SIZE_HINT_P_RESIZE_INC | XCB_ICCCM_SIZE_HINT_BASE_SIZE)
2641→       && c->size_hints.width_inc && c->size_hints.height_inc)
2642→    {
2643→        uint16_t t1 = geometry.width, t2 = geometry.height;
2644→        unsigned_subtract(t1, basew);
2645→        unsigned_subtract(t2, baseh);
2646→        geometry.width -= t1 % c->size_hints.width_inc;
2647→        geometry.height -= t2 % c->size_hints.height_inc;
2648→    }
2649→
2650→    client_add_titlebar_geometry(c, &geometry);
2651→    return geometry;
2652→}
