client_set_bounds(c, geo.width, geo.height);
c->geometry = geo;
applybounds(c, bbox);

/* Apply aspect ratio constraint (Wayland equivalent of ICCCM aspect hints) */
if (c->aspect_ratio > 0 && !c->fullscreen && !c->maximized) {
	int bw2 = 2 * c->bw;
	int w = c->geometry.width - bw2;
	int h = c->geometry.height - bw2;
	if (w > 0 && h > 0) {
		double current = (double)w / h;
		if (current > c->aspect_ratio) {
			/* Too wide, reduce width to match */
			c->geometry.width = (int)(h * c->aspect_ratio) + bw2;
		} else if (current < c->aspect_ratio) {
			/* Too tall, reduce height to match */
			c->geometry.height = (int)(w / c->aspect_ratio) + bw2;
		}
	}
}

/* Apply to wlroots rendering */
apply_geometry_to_wlroots(c);

/* Emit signal for geometry change listeners */

