/* mark a pending resize as completed */
if (c->resize) {
	if (c->resize <= c->surface.xdg->current.configure_serial) {
		c->resize = 0;
		/* Client completed its first configure - it has real content and
		 * wl_pointer is bound. Set pointer focus directly if cursor is
		 * within this client (catches first-client-after-startup case
		 * where mapnotify's pointer_enter was too early). */
		if (client_surface(c) && client_surface(c)->mapped
				&& cursor->x >= c->geometry.x
				&& cursor->x < c->geometry.x + c->geometry.width
				&& cursor->y >= c->geometry.y
				&& cursor->y < c->geometry.y + c->geometry.height) {
			pointerfocus(c, client_surface(c),
				cursor->x - c->geometry.x - c->bw,
				cursor->y - c->geometry.y - c->bw, 0);
		}
	}

