  41→		struct wlr_surface **surface, double *sx, double *sy) {
  42→	struct wlr_scene_node *scene_node = NULL;
  43→
  44→	struct wlr_scene_node *node;
  45→	wl_list_for_each_reverse(node, &root->layer_tree->children, link) {
  46→		struct wlr_scene_tree *layer = wlr_scene_tree_from_node(node);
  47→
  48→		bool non_interactive = scene_descriptor_try_get(&layer->node,
  49→			SWAY_SCENE_DESC_NON_INTERACTIVE);
  50→		if (non_interactive) {
  51→			continue;
  52→		}
  53→
  54→		scene_node = wlr_scene_node_at(&layer->node, lx, ly, sx, sy);
  55→		if (scene_node) {
  56→			break;
  57→		}
  58→	}
  59→
  60→	if (scene_node) {
  61→		// determine what wlr_surface we clicked on
  62→		if (scene_node->type == WLR_SCENE_NODE_BUFFER) {
  63→			struct wlr_scene_buffer *scene_buffer =
  64→				wlr_scene_buffer_from_node(scene_node);
  65→			struct wlr_scene_surface *scene_surface =
  66→				wlr_scene_surface_try_from_buffer(scene_buffer);
  67→
  68→			if (scene_surface) {
  69→				*surface = scene_surface->surface;
  70→			}
  71→		}
  72→
  73→		// determine what container we clicked on
  74→		struct wlr_scene_node *current = scene_node;
  75→		while (true) {
  76→			struct sway_container *con = scene_descriptor_try_get(current,
  77→				SWAY_SCENE_DESC_CONTAINER);
  78→
  79→			if (!con) {
  80→				struct sway_view *view = scene_descriptor_try_get(current,
  81→					SWAY_SCENE_DESC_VIEW);
  82→				if (view) {
  83→					con = view->container;
  84→				}
  85→			}
  86→
  87→			if (!con) {
  88→				struct sway_popup_desc *popup =
  89→					scene_descriptor_try_get(current, SWAY_SCENE_DESC_POPUP);
  90→				if (popup && popup->view) {
  91→					con = popup->view->container;
  92→				}
  93→			}
  94→
  95→			if (con && (!con->view || con->view->surface)) {
  96→				return &con->node;
  97→			}
  98→
  99→			if (scene_descriptor_try_get(current, SWAY_SCENE_DESC_LAYER_SHELL)) {
 100→				// We don't want to feed through the current workspace on
 101→				// layer shells
 102→				return NULL;
 103→			}
 104→
 105→#if WLR_HAS_XWAYLAND
 106→			if (scene_descriptor_try_get(current, SWAY_SCENE_DESC_XWAYLAND_UNMANAGED)) {
 107→				return NULL;
 108→			}
 109→#endif
 110→
 111→			if (!current->parent) {
 112→				break;
 113→			}
 114→
 115→			current = &current->parent->node;
 116→		}
 117→	}
 118→
 119→	// if we aren't on a container, determine what workspace we are on
 120→	struct wlr_output *wlr_output = wlr_output_layout_output_at(
 121→			root->output_layout, lx, ly);
 122→	if (wlr_output == NULL) {
 123→		return NULL;
 124→	}
 125→
 126→	struct sway_output *output = wlr_output->data;
 127→	if (!output || !output->enabled) {
 128→		// output is being destroyed or is being enabled
 129→		return NULL;
 130→	}
 131→
 132→	struct sway_workspace *ws = output_get_active_workspace(output);
 133→	if (!ws) {
 134→		return NULL;
 135→	}
 136→
 137→	return &ws->node;
 138→}
