 189→int cursor_get_timeout(struct sway_cursor *cursor) {
 190→	if (cursor->pressed_button_count > 0) {
 191→		// Do not hide cursor unless all buttons are released
 192→		return 0;
 193→	}
 194→
 195→	struct seat_config *sc = seat_get_config(cursor->seat);
 196→	if (!sc) {
 197→		sc = seat_get_config_by_name("*");
 198→	}
 199→	int timeout = sc ? sc->hide_cursor_timeout : 0;
 200→	if (timeout < 0) {
 201→		timeout = 0;
 202→	}
 203→	return timeout;
 204→}
