 206→void cursor_notify_key_press(struct sway_cursor *cursor) {
 207→	if (cursor->hidden) {
 208→		return;
 209→	}
 210→
 211→	if (cursor->hide_when_typing == HIDE_WHEN_TYPING_DEFAULT) {
 212→		// No cached value, need to lookup in the seat_config
 213→		const struct seat_config *seat_config = seat_get_config(cursor->seat);
 214→		if (!seat_config) {
 215→			seat_config = seat_get_config_by_name("*");
 216→			if (!seat_config) {
 217→				return;
 218→			}
 219→		}
 220→		cursor->hide_when_typing = seat_config->hide_cursor_when_typing;
 221→		// The default is currently disabled
 222→		if (cursor->hide_when_typing == HIDE_WHEN_TYPING_DEFAULT) {
 223→			cursor->hide_when_typing = HIDE_WHEN_TYPING_DISABLE;
 224→		}
 225→	}
 226→
 227→	if (cursor->hide_when_typing == HIDE_WHEN_TYPING_ENABLE) {
 228→		cursor_hide(cursor);
 229→	}
 230→}
