 290→void pointer_motion(struct sway_cursor *cursor, uint32_t time_msec,
 291→		struct wlr_input_device *device, double dx, double dy,
 292→		double dx_unaccel, double dy_unaccel) {
 293→	wlr_relative_pointer_manager_v1_send_relative_motion(
 294→		server.relative_pointer_manager,
 295→		cursor->seat->wlr_seat, (uint64_t)time_msec * 1000,
 296→		dx, dy, dx_unaccel, dy_unaccel);
 297→
 298→	// Only apply pointer constraints to real pointer input.
 299→	if (cursor->active_constraint && device->type == WLR_INPUT_DEVICE_POINTER) {
 300→		struct wlr_surface *surface = NULL;
 301→		double sx, sy;
 302→		node_at_coords(cursor->seat,
 303→			cursor->cursor->x, cursor->cursor->y, &surface, &sx, &sy);
 304→
 305→		if (cursor->active_constraint->surface != surface) {
 306→			return;
 307→		}
 308→
 309→		double sx_confined, sy_confined;
 310→		if (!wlr_region_confine(&cursor->confine, sx, sy, sx + dx, sy + dy,
 311→				&sx_confined, &sy_confined)) {
 312→			return;
 313→		}
 314→
 315→		dx = sx_confined - sx;
 316→		dy = sy_confined - sy;
 317→	}
 318→
 319→	wlr_cursor_move(cursor->cursor, device, dx, dy);
 320→
 321→	seatop_pointer_motion(cursor->seat, time_msec);
 322→}
