 503→static double apply_mapping_from_coord(double low, double high, double value) {
 504→	if (isnan(value)) {
 505→		return value;
 506→	}
 507→
 508→	return (value - low) / (high - low);
 509→}
 510→
 511→static void apply_mapping_from_region(struct wlr_input_device *device,
 512→		struct input_config_mapped_from_region *region, double *x, double *y) {
 513→	double x1 = region->x1, x2 = region->x2;
 514→	double y1 = region->y1, y2 = region->y2;
 515→
 516→	if (region->mm && device->type == WLR_INPUT_DEVICE_TABLET) {
 517→		struct wlr_tablet *tablet = wlr_tablet_from_input_device(device);
 518→		if (tablet->width_mm == 0 || tablet->height_mm == 0) {
 519→			return;
 520→		}
 521→		x1 /= tablet->width_mm;
 522→		x2 /= tablet->width_mm;
 523→		y1 /= tablet->height_mm;
 524→		y2 /= tablet->height_mm;
 525→	}
 526→
 527→	*x = apply_mapping_from_coord(x1, x2, *x);
 528→	*y = apply_mapping_from_coord(y1, y2, *y);
 529→}
 530→
 531→static void handle_tablet_tool_position(struct sway_cursor *cursor,
 532→		struct sway_tablet_tool *tool,
 533→		bool change_x, bool change_y,
 534→		double x, double y, double dx, double dy,
 535→		int32_t time_msec) {
 536→
 537→	if (!change_x && !change_y) {
 538→		return;
 539→	}
 540→
 541→	struct sway_tablet *tablet = tool->tablet;
 542→	struct sway_input_device *input_device = tablet->seat_device->input_device;
 543→	struct input_config *ic = input_device_get_config(input_device);
 544→	if (ic != NULL && ic->mapped_from_region != NULL) {
 545→		apply_mapping_from_region(input_device->wlr_device,
 546→			ic->mapped_from_region, &x, &y);
 547→	}
 548→
 549→	switch (tool->mode) {
 550→	case SWAY_TABLET_TOOL_MODE_ABSOLUTE:
 551→		wlr_cursor_warp_absolute(cursor->cursor, input_device->wlr_device,
 552→			change_x ? x : NAN, change_y ? y : NAN);
 553→		break;
 554→	case SWAY_TABLET_TOOL_MODE_RELATIVE:
 555→		wlr_cursor_move(cursor->cursor, input_device->wlr_device, dx, dy);
 556→		break;
 557→	}
 558→
 559→	double sx, sy;
 560→	struct wlr_surface *surface = NULL;
 561→	struct sway_seat *seat = cursor->seat;
 562→	node_at_coords(seat, cursor->cursor->x, cursor->cursor->y, &surface, &sx, &sy);
 563→
 564→	// The logic for whether we should send a tablet event or an emulated pointer
 565→	// event is tricky. It comes down to:
 566→	// * If we began a drag on a non-tablet surface (simulating_pointer_from_tool_tip),
 567→	//   then we should continue sending emulated pointer events regardless of
 568→	//   whether the surface currently under us accepts tablet or not.
 569→	// * Otherwise, if we are over a surface that accepts tablet, then we should
 570→	//   send tablet events.
 571→	// * If we began a drag over a tablet surface, we should continue sending
 572→	//   tablet events until the drag is released, even if we are now over a
 573→	//   non-tablet surface.
 574→	if (!cursor->simulating_pointer_from_tool_tip &&
 575→			((surface && wlr_surface_accepts_tablet_v2(surface, tablet->tablet_v2)) ||
 576→				wlr_tablet_tool_v2_has_implicit_grab(tool->tablet_v2_tool))) {
 577→		seatop_tablet_tool_motion(seat, tool, time_msec);
 578→	} else {
 579→		wlr_tablet_v2_tablet_tool_notify_proximity_out(tool->tablet_v2_tool);
 580→		pointer_motion(cursor, time_msec, input_device->wlr_device, dx, dy, dx, dy);
 581→		wlr_seat_pointer_notify_frame(cursor->seat->wlr_seat);
 582→	}
 583→}
 584→
 585→static void handle_tool_axis(struct wl_listener *listener, void *data) {
 586→	struct sway_cursor *cursor = wl_container_of(listener, cursor, tool_axis);
 587→	struct wlr_tablet_tool_axis_event *event = data;
 588→	cursor_handle_activity_from_device(cursor, &event->tablet->base);
 589→
 590→	struct sway_tablet_tool *sway_tool = event->tool->data;
 591→	if (!sway_tool) {
 592→		sway_log(SWAY_DEBUG, "tool axis before proximity");
 593→		return;
 594→	}
 595→
 596→	handle_tablet_tool_position(cursor, sway_tool,
 597→		event->updated_axes & WLR_TABLET_TOOL_AXIS_X,
 598→		event->updated_axes & WLR_TABLET_TOOL_AXIS_Y,
 599→		event->x, event->y, event->dx, event->dy, event->time_msec);
 600→
 601→	if (event->updated_axes & WLR_TABLET_TOOL_AXIS_PRESSURE) {
 602→		wlr_tablet_v2_tablet_tool_notify_pressure(
 603→			sway_tool->tablet_v2_tool, event->pressure);
 604→	}
 605→
 606→	if (event->updated_axes & WLR_TABLET_TOOL_AXIS_DISTANCE) {
 607→		wlr_tablet_v2_tablet_tool_notify_distance(
 608→			sway_tool->tablet_v2_tool, event->distance);
 609→	}
 610→
 611→	if (event->updated_axes & WLR_TABLET_TOOL_AXIS_TILT_X) {
 612→		sway_tool->tilt_x = event->tilt_x;
 613→	}
 614→
 615→	if (event->updated_axes & WLR_TABLET_TOOL_AXIS_TILT_Y) {
 616→		sway_tool->tilt_y = event->tilt_y;
 617→	}
 618→
 619→	if (event->updated_axes & (WLR_TABLET_TOOL_AXIS_TILT_X | WLR_TABLET_TOOL_AXIS_TILT_Y)) {
 620→		wlr_tablet_v2_tablet_tool_notify_tilt(
 621→			sway_tool->tablet_v2_tool,
 622→			sway_tool->tilt_x, sway_tool->tilt_y);
 623→	}
 624→
 625→	if (event->updated_axes & WLR_TABLET_TOOL_AXIS_ROTATION) {
 626→		wlr_tablet_v2_tablet_tool_notify_rotation(
 627→			sway_tool->tablet_v2_tool, event->rotation);
 628→	}
 629→
 630→	if (event->updated_axes & WLR_TABLET_TOOL_AXIS_SLIDER) {
 631→		wlr_tablet_v2_tablet_tool_notify_slider(
 632→			sway_tool->tablet_v2_tool, event->slider);
 633→	}
 634→
 635→	if (event->updated_axes & WLR_TABLET_TOOL_AXIS_WHEEL) {
 636→		wlr_tablet_v2_tablet_tool_notify_wheel(
 637→			sway_tool->tablet_v2_tool, event->wheel_delta, 0);
