 641→static void handle_tool_tip(struct wl_listener *listener, void *data) {
 642→	struct sway_cursor *cursor = wl_container_of(listener, cursor, tool_tip);
 643→	struct wlr_tablet_tool_tip_event *event = data;
 644→	cursor_handle_activity_from_device(cursor, &event->tablet->base);
 645→
 646→	struct sway_tablet_tool *sway_tool = event->tool->data;
 647→	if (!sway_tool) {
 648→		sway_log(SWAY_DEBUG, "tool tip before proximity");
 649→		return;
 650→	}
 651→
 652→	struct wlr_tablet_v2_tablet *tablet_v2 = sway_tool->tablet->tablet_v2;
 653→	struct sway_seat *seat = cursor->seat;
 654→
 655→
 656→	double sx, sy;
 657→	struct wlr_surface *surface = NULL;
 658→	node_at_coords(seat, cursor->cursor->x, cursor->cursor->y,
 659→		&surface, &sx, &sy);
 660→
 661→	if (cursor->simulating_pointer_from_tool_tip &&
 662→			event->state == WLR_TABLET_TOOL_TIP_UP) {
 663→		cursor->simulating_pointer_from_tool_tip = false;
 664→		dispatch_cursor_button(cursor, &event->tablet->base, event->time_msec,
 665→			BTN_LEFT, WL_POINTER_BUTTON_STATE_RELEASED);
 666→		wlr_seat_pointer_notify_frame(cursor->seat->wlr_seat);
 667→	} else if (!surface || !wlr_surface_accepts_tablet_v2(surface, tablet_v2)) {
 668→		// If we started holding the tool tip down on a surface that accepts
 669→		// tablet v2, we should notify that surface if it gets released over a
 670→		// surface that doesn't support v2.
 671→		if (event->state == WLR_TABLET_TOOL_TIP_UP) {
 672→			seatop_tablet_tool_tip(seat, sway_tool, event->time_msec,
 673→				WLR_TABLET_TOOL_TIP_UP);
 674→		} else {
 675→			cursor->simulating_pointer_from_tool_tip = true;
 676→			dispatch_cursor_button(cursor, &event->tablet->base,
 677→				event->time_msec, BTN_LEFT, WL_POINTER_BUTTON_STATE_PRESSED);
 678→			wlr_seat_pointer_notify_frame(cursor->seat->wlr_seat);
 679→		}
 680→	} else {
 681→		seatop_tablet_tool_tip(seat, sway_tool, event->time_msec, event->state);
 682→	}
 683→}
