 813→static void check_constraint_region(struct sway_cursor *cursor) {
 814→	struct wlr_pointer_constraint_v1 *constraint = cursor->active_constraint;
 815→	pixman_region32_t *region = &constraint->region;
 816→	struct sway_view *view = view_from_wlr_surface(constraint->surface);
 817→	if (cursor->active_confine_requires_warp && view) {
 818→		cursor->active_confine_requires_warp = false;
 819→
 820→		struct sway_container *con = view->container;
 821→
 822→		double sx = cursor->cursor->x - con->pending.content_x + view->geometry.x;
 823→		double sy = cursor->cursor->y - con->pending.content_y + view->geometry.y;
 824→
 825→		if (!pixman_region32_contains_point(region,
 826→				floor(sx), floor(sy), NULL)) {
 827→			int nboxes;
 828→			pixman_box32_t *boxes = pixman_region32_rectangles(region, &nboxes);
 829→			if (nboxes > 0) {
 830→				double sx = (boxes[0].x1 + boxes[0].x2) / 2.;
 831→				double sy = (boxes[0].y1 + boxes[0].y2) / 2.;
 832→
 833→				wlr_cursor_warp_closest(cursor->cursor, NULL,
 834→					sx + con->pending.content_x - view->geometry.x,
 835→					sy + con->pending.content_y - view->geometry.y);
 836→
 837→				cursor_rebase(cursor);
 838→			}
 839→		}
 840→	}
 841→
 842→	// A locked pointer will result in an empty region, thus disallowing all movement
 843→	if (constraint->type == WLR_POINTER_CONSTRAINT_V1_CONFINED) {
 844→		pixman_region32_copy(&cursor->confine, region);
 845→	} else {
 846→		pixman_region32_clear(&cursor->confine);
 847→	}
 848→}
