1059→struct sway_cursor *sway_cursor_create(struct sway_seat *seat) {
1060→	struct sway_cursor *cursor = calloc(1, sizeof(struct sway_cursor));
1061→	if (!sway_assert(cursor, "could not allocate sway cursor")) {
1062→		return NULL;
1063→	}
1064→
1065→	struct wlr_cursor *wlr_cursor = wlr_cursor_create();
1066→	if (!sway_assert(wlr_cursor, "could not allocate wlr cursor")) {
1067→		free(cursor);
1068→		return NULL;
1069→	}
1070→
1071→	cursor->previous.x = wlr_cursor->x;
1072→	cursor->previous.y = wlr_cursor->y;
1073→
1074→	cursor->seat = seat;
1075→	wlr_cursor_attach_output_layout(wlr_cursor, root->output_layout);
1076→
1077→	cursor->hide_source = wl_event_loop_add_timer(server.wl_event_loop,
1078→			hide_notify, cursor);
1079→
1080→	wl_list_init(&cursor->image_surface_destroy.link);
1081→	cursor->image_surface_destroy.notify = handle_image_surface_destroy;
1082→
1083→	wl_signal_add(&wlr_cursor->events.hold_begin, &cursor->hold_begin);
1084→	cursor->hold_begin.notify = handle_pointer_hold_begin;
1085→	wl_signal_add(&wlr_cursor->events.hold_end, &cursor->hold_end);
1086→	cursor->hold_end.notify = handle_pointer_hold_end;
1087→
1088→	wl_signal_add(&wlr_cursor->events.pinch_begin, &cursor->pinch_begin);
1089→	cursor->pinch_begin.notify = handle_pointer_pinch_begin;
1090→	wl_signal_add(&wlr_cursor->events.pinch_update, &cursor->pinch_update);
1091→	cursor->pinch_update.notify = handle_pointer_pinch_update;
1092→	wl_signal_add(&wlr_cursor->events.pinch_end, &cursor->pinch_end);
