1161→/**
1162→ * Warps the cursor to the middle of the container argument.
1163→ * Does nothing if the cursor is already inside the container and `force` is
1164→ * false. If container is NULL, returns without doing anything.
1165→ */
1166→void cursor_warp_to_container(struct sway_cursor *cursor,
1167→		struct sway_container *container, bool force) {
1168→	if (!container) {
1169→		return;
1170→	}
1171→
1172→	struct wlr_box box;
1173→	container_get_box(container, &box);
1174→	if (!force && wlr_box_contains_point(&box, cursor->cursor->x,
1175→			cursor->cursor->y)) {
1176→		return;
1177→	}
1178→
1179→	double x = container->pending.x + container->pending.width / 2.0;
1180→	double y = container->pending.y + container->pending.height / 2.0;
1181→
1182→	wlr_cursor_warp(cursor->cursor, NULL, x, y);
1183→	cursor_unhide(cursor);
1184→}
