1186→/**
1187→ * Warps the cursor to the middle of the workspace argument.
1188→ * If workspace is NULL, returns without doing anything.
1189→ */
1190→void cursor_warp_to_workspace(struct sway_cursor *cursor,
1191→		struct sway_workspace *workspace) {
1192→	if (!workspace) {
1193→		return;
1194→	}
1195→
1196→	double x = workspace->x + workspace->width / 2.0;
1197→	double y = workspace->y + workspace->height / 2.0;
1198→
1199→	wlr_cursor_warp(cursor->cursor, NULL, x, y);
1200→	cursor_unhide(cursor);
1201→}
