1203→uint32_t get_mouse_bindsym(const char *name, char **error) {
1204→	if (strncasecmp(name, "button", strlen("button")) == 0) {
1205→		// Map to x11 mouse buttons
1206→		int number = name[strlen("button")] - '0';
1207→		if (number < 1 || number > 9 || strlen(name) > strlen("button0")) {
1208→			*error = strdup("Only buttons 1-9 are supported. For other mouse "
1209→					"buttons, use the name of the event code.");
1210→			return 0;
1211→		}
1212→		static const uint32_t buttons[] = {BTN_LEFT, BTN_MIDDLE, BTN_RIGHT,
1213→			SWAY_SCROLL_UP, SWAY_SCROLL_DOWN, SWAY_SCROLL_LEFT,
1214→			SWAY_SCROLL_RIGHT, BTN_SIDE, BTN_EXTRA};
1215→		return buttons[number - 1];
1216→	} else if (has_prefix(name, "BTN_")) {
1217→		// Get event code from name
1218→		int code = libevdev_event_code_from_name(EV_KEY, name);
1219→		if (code == -1) {
1220→			*error = format_str("Unknown event %s", name);
1221→			return 0;
1222→		}
1223→		return code;
1224→	}
1225→	return 0;
1226→}
1227→
1228→uint32_t get_mouse_bindcode(const char *name, char **error) {
1229→	// Validate event code
1230→	errno = 0;
1231→	char *endptr;
1232→	int code = strtol(name, &endptr, 10);
1233→	if (endptr == name && code <= 0) {
1234→		*error = strdup("Button event code must be a positive integer.");
1235→		return 0;
1236→	} else if (errno == ERANGE) {
1237→		*error = strdup("Button event code out of range.");
1238→		return 0;
1239→	}
1240→	const char *event = libevdev_event_code_get_name(EV_KEY, code);
1241→	if (!event || !has_prefix(event, "BTN_")) {
1242→		*error = format_str("Event code %d (%s) is not a button",
1243→			code, event ? event : "(null)");
1244→		return 0;
1245→	}
1246→	return code;
1247→}
1248→
1249→uint32_t get_mouse_button(const char *name, char **error) {
1250→	uint32_t button = get_mouse_bindsym(name, error);
1251→	if (!button && !*error) {
1252→		button = get_mouse_bindcode(name, error);
1253→	}
1254→	return button;
1255→}
