1257→const char *get_mouse_button_name(uint32_t button) {
1258→	const char *name = libevdev_event_code_get_name(EV_KEY, button);
1259→	if (!name) {
1260→		if (button == SWAY_SCROLL_UP) {
1261→			name = "SWAY_SCROLL_UP";
1262→		} else if (button == SWAY_SCROLL_DOWN) {
1263→			name = "SWAY_SCROLL_DOWN";
1264→		} else if (button == SWAY_SCROLL_LEFT) {
1265→			name = "SWAY_SCROLL_LEFT";
1266→		} else if (button == SWAY_SCROLL_RIGHT) {
1267→			name = "SWAY_SCROLL_RIGHT";
1268→		}
1269→	}
1270→	return name;
1271→}
