1273→static void warp_to_constraint_cursor_hint(struct sway_cursor *cursor) {
1274→	struct wlr_pointer_constraint_v1 *constraint = cursor->active_constraint;
1275→
1276→	if (constraint->current.cursor_hint.enabled) {
1277→		double sx = constraint->current.cursor_hint.x;
1278→		double sy = constraint->current.cursor_hint.y;
1279→
1280→		struct sway_view *view = view_from_wlr_surface(constraint->surface);
1281→		if (!view) {
1282→			return;
1283→		}
1284→
1285→		struct sway_container *con = view->container;
1286→
1287→		double lx = sx + con->pending.content_x - view->geometry.x;
1288→		double ly = sy + con->pending.content_y - view->geometry.y;
1289→
1290→		wlr_cursor_warp(cursor->cursor, NULL, lx, ly);
1291→
1292→		// Warp the pointer as well, so that on the next pointer rebase we don't
1293→		// send an unexpected synthetic motion event to clients.
1294→		wlr_seat_pointer_warp(constraint->seat, sx, sy);
1295→	}
1296→}
