1298→void handle_constraint_destroy(struct wl_listener *listener, void *data) {
1299→	struct sway_pointer_constraint *sway_constraint =
1300→		wl_container_of(listener, sway_constraint, destroy);
1301→	struct wlr_pointer_constraint_v1 *constraint = data;
1302→	struct sway_cursor *cursor = sway_constraint->cursor;
1303→
1304→	wl_list_remove(&sway_constraint->set_region.link);
1305→	wl_list_remove(&sway_constraint->destroy.link);
1306→
1307→	if (cursor->active_constraint == constraint) {
1308→		warp_to_constraint_cursor_hint(cursor);
1309→
1310→		if (cursor->constraint_commit.link.next != NULL) {
1311→			wl_list_remove(&cursor->constraint_commit.link);
1312→		}
1313→		wl_list_init(&cursor->constraint_commit.link);
1314→		cursor->active_constraint = NULL;
1315→	}
1316→
1317→	free(sway_constraint);
1318→}
