1341→void sway_cursor_constrain(struct sway_cursor *cursor,
1342→		struct wlr_pointer_constraint_v1 *constraint) {
1343→	struct seat_config *config = seat_get_config(cursor->seat);
1344→	if (!config) {
1345→		config = seat_get_config_by_name("*");
1346→	}
1347→
1348→	if (!config || config->allow_constrain == CONSTRAIN_DISABLE) {
1349→		return;
1350→	}
1351→
1352→	if (cursor->active_constraint == constraint) {
1353→		return;
1354→	}
1355→
1356→	wl_list_remove(&cursor->constraint_commit.link);
1357→	if (cursor->active_constraint) {
1358→		if (constraint == NULL) {
1359→			warp_to_constraint_cursor_hint(cursor);
1360→		}
1361→		wlr_pointer_constraint_v1_send_deactivated(
1362→			cursor->active_constraint);
1363→	}
1364→
1365→	cursor->active_constraint = constraint;
1366→
1367→	if (constraint == NULL) {
1368→		wl_list_init(&cursor->constraint_commit.link);
1369→		return;
1370→	}
1371→
1372→	cursor->active_confine_requires_warp = true;
1373→
1374→	// FIXME: Big hack, stolen from wlr_pointer_constraints_v1.c:121.
1375→	// This is necessary because the focus may be set before the surface
1376→	// has finished committing, which means that warping won't work properly,
1377→	// since this code will be run *after* the focus has been set.
1378→	// That is why we duplicate the code here.
1379→	if (pixman_region32_not_empty(&constraint->current.region)) {
1380→		pixman_region32_intersect(&constraint->region,
1381→			&constraint->surface->input_region, &constraint->current.region);
1382→	} else {
1383→		pixman_region32_copy(&constraint->region,
1384→			&constraint->surface->input_region);
1385→	}
1386→
1387→	check_constraint_region(cursor);
1388→
1389→	wlr_pointer_constraint_v1_send_activated(constraint);
1390→
1391→	cursor->constraint_commit.notify = handle_constraint_commit;
1392→	wl_signal_add(&constraint->surface->events.commit,
1393→		&cursor->constraint_commit);
1394→}
