  73→static void handle_seat_destroy(struct wl_listener *listener, void *data) {
  74→	struct sway_seat *seat = wl_container_of(listener, seat, destroy);
  75→
  76→	if (seat == config->handler_context.seat) {
  77→		config->handler_context.seat = input_manager_get_default_seat();
  78→	}
  79→	struct sway_seat_device *seat_device, *next;
  80→	wl_list_for_each_safe(seat_device, next, &seat->devices, link) {
  81→		seat_device_destroy(seat_device);
  82→	}
  83→	struct sway_seat_node *seat_node, *next_seat_node;
  84→	wl_list_for_each_safe(seat_node, next_seat_node, &seat->focus_stack,
  85→			link) {
  86→		seat_node_destroy(seat_node);
  87→	}
  88→	sway_input_method_relay_finish(&seat->im_relay);
  89→	sway_cursor_destroy(seat->cursor);
  90→	wl_list_remove(&seat->new_node.link);
  91→	wl_list_remove(&seat->request_start_drag.link);
  92→	wl_list_remove(&seat->start_drag.link);
  93→	wl_list_remove(&seat->request_set_selection.link);
  94→	wl_list_remove(&seat->request_set_primary_selection.link);
  95→	wl_list_remove(&seat->link);
  96→	wl_list_remove(&seat->destroy.link);
  97→	for (int i = 0; i < seat->deferred_bindings->length; i++) {
  98→		free_sway_binding(seat->deferred_bindings->items[i]);
  99→	}
 100→	wlr_scene_node_destroy(&seat->scene_tree->node);
 101→	list_free(seat->deferred_bindings);
 102→	free(seat->prev_workspace_name);
 103→	free(seat);
 104→}
