 219→struct sway_container *seat_get_focus_inactive_view(struct sway_seat *seat,
 220→		struct sway_node *ancestor) {
 221→	if (node_is_view(ancestor)) {
 222→		return ancestor->sway_container;
 223→	}
 224→	struct sway_seat_node *current;
 225→	wl_list_for_each(current, &seat->focus_stack, link) {
 226→		struct sway_node *node = current->node;
 227→		if (node_is_view(node) && node_has_ancestor(node, ancestor)) {
 228→			return node->sway_container;
 229→		}
 230→	}
 231→	return NULL;
 232→}
 233→
 234→static void handle_seat_node_destroy(struct wl_listener *listener, void *data) {
 235→	struct sway_seat_node *seat_node =
 236→		wl_container_of(listener, seat_node, destroy);
 237→	struct sway_seat *seat = seat_node->seat;
 238→	struct sway_node *node = seat_node->node;
 239→	struct sway_node *parent = node_get_parent(node);
 240→	struct sway_node *focus = seat_get_focus(seat);
 241→
 242→	if (node->type == N_WORKSPACE) {
 243→		seat_node_destroy(seat_node);
 244→		// If an unmanaged or layer surface is focused when an output gets
 245→		// disabled and an empty workspace on the output was focused by the
 246→		// seat, the seat needs to refocus its focus inactive to update the
 247→		// value of seat->workspace.
 248→		if (seat->workspace == node->sway_workspace) {
 249→			struct sway_node *node = seat_get_focus_inactive(seat, &root->node);
 250→			seat_set_focus(seat, NULL);
 251→			if (node) {
 252→				seat_set_focus(seat, node);
 253→			} else {
 254→				seat->workspace = NULL;
 255→			}
 256→		}
 257→		return;
 258→	}
 259→
 260→	// Even though the container being destroyed might be nowhere near the
 261→	// focused container, we still need to set focus_inactive on a sibling of
 262→	// the container being destroyed.
 263→	bool needs_new_focus = focus &&
 264→		(focus == node || node_has_ancestor(focus, node));
 265→
 266→	seat_node_destroy(seat_node);
 267→
 268→	if (!parent && !needs_new_focus) {
 269→		// Destroying a container that is no longer in the tree
 270→		return;
 271→	}
 272→
 273→	// Find new focus_inactive (ie. sibling, or workspace if no siblings left)
 274→	struct sway_node *next_focus = NULL;
 275→	while (next_focus == NULL && parent != NULL) {
 276→		struct sway_container *con =
 277→			seat_get_focus_inactive_view(seat, parent);
 278→		next_focus = con ? &con->node : NULL;
 279→
 280→		if (next_focus == NULL && parent->type == N_WORKSPACE) {
 281→			next_focus = parent;
 282→			break;
 283→		}
 284→
 285→		parent = node_get_parent(parent);
 286→	}
 287→
 288→	if (!next_focus) {
 289→		struct sway_workspace *ws = seat_get_last_known_workspace(seat);
 290→		if (!ws) {
 291→			return;
 292→		}
 293→		struct sway_container *con =
 294→			seat_get_focus_inactive_view(seat, &ws->node);
 295→		next_focus = con ? &(con->node) : &(ws->node);
 296→	}
 297→
 298→	if (next_focus->type == N_WORKSPACE &&
 299→			!workspace_is_visible(next_focus->sway_workspace)) {
 300→		// Do not change focus to a non-visible workspace
 301→		return;
 302→	}
 303→
 304→	if (needs_new_focus) {
 305→		// Make sure the workspace IPC event gets sent
 306→		if (node->type == N_CONTAINER && node->sway_container->scratchpad) {
 307→			seat_set_focus(seat, NULL);
 308→		}
 309→		// The structure change might have caused it to move up to the top of
 310→		// the focus stack without sending focus notifications to the view
 311→		if (seat_get_focus(seat) == next_focus) {
 312→			seat_send_focus(next_focus, seat);
 313→		} else {
 314→			seat_set_focus(seat, next_focus);
 315→		}
 316→	} else {
 317→		// Setting focus_inactive
 318→		focus = seat_get_focus_inactive(seat, &root->node);
 319→		seat_set_raw_focus(seat, next_focus);
 320→		if (focus->type == N_CONTAINER && focus->sway_container->pending.workspace) {
 321→			seat_set_raw_focus(seat, &focus->sway_container->pending.workspace->node);
 322→		}
 323→		seat_set_raw_focus(seat, focus);
 324→	}
 325→}
