 512→struct sway_seat *seat_create(const char *seat_name) {
 513→	struct sway_seat *seat = calloc(1, sizeof(struct sway_seat));
 514→	if (!seat) {
 515→		return NULL;
 516→	}
 517→
 518→	bool failed = false;
 519→	seat->scene_tree = alloc_scene_tree(root->layers.seat, &failed);
 520→	seat->drag_icons = alloc_scene_tree(seat->scene_tree, &failed);
 521→	if (failed) {
 522→		wlr_scene_node_destroy(&seat->scene_tree->node);
 523→		free(seat);
 524→		return NULL;
 525→	}
 526→
 527→	seat->wlr_seat = wlr_seat_create(server.wl_display, seat_name);
 528→	if (!sway_assert(seat->wlr_seat, "could not allocate seat")) {
 529→		wlr_scene_node_destroy(&seat->scene_tree->node);
 530→		free(seat);
 531→		return NULL;
 532→	}
 533→	seat->wlr_seat->data = seat;
 534→
 535→	seat->cursor = sway_cursor_create(seat);
 536→	if (!seat->cursor) {
 537→		wlr_scene_node_destroy(&seat->scene_tree->node);
 538→		wlr_seat_destroy(seat->wlr_seat);
 539→		free(seat);
 540→		return NULL;
 541→	}
 542→
 543→	seat->destroy.notify = handle_seat_destroy;
 544→	wl_signal_add(&seat->wlr_seat->events.destroy, &seat->destroy);
 545→
 546→	seat->idle_inhibit_sources = seat->idle_wake_sources =
 547→		IDLE_SOURCE_KEYBOARD |
 548→		IDLE_SOURCE_POINTER |
 549→		IDLE_SOURCE_TOUCH |
 550→		IDLE_SOURCE_TABLET_PAD |
 551→		IDLE_SOURCE_TABLET_TOOL |
 552→		IDLE_SOURCE_SWITCH;
 553→
 554→	// init the focus stack
 555→	wl_list_init(&seat->focus_stack);
 556→
 557→	wl_list_init(&seat->devices);
 558→
 559→	root_for_each_workspace(collect_focus_workspace_iter, seat);
 560→	root_for_each_container(collect_focus_container_iter, seat);
 561→
 562→	seat->deferred_bindings = create_list();
 563→
 564→	wl_signal_add(&root->events.new_node, &seat->new_node);
 565→	seat->new_node.notify = handle_new_node;
 566→
 567→	wl_signal_add(&seat->wlr_seat->events.request_start_drag,
 568→		&seat->request_start_drag);
 569→	seat->request_start_drag.notify = handle_request_start_drag;
 570→
 571→	wl_signal_add(&seat->wlr_seat->events.start_drag, &seat->start_drag);
 572→	seat->start_drag.notify = handle_start_drag;
 573→
 574→	wl_signal_add(&seat->wlr_seat->events.request_set_selection,
 575→		&seat->request_set_selection);
 576→	seat->request_set_selection.notify = handle_request_set_selection;
 577→
 578→	wl_signal_add(&seat->wlr_seat->events.request_set_primary_selection,
 579→		&seat->request_set_primary_selection);
 580→	seat->request_set_primary_selection.notify =
 581→		handle_request_set_primary_selection;
 582→
 583→	wl_list_init(&seat->keyboard_groups);
 584→	wl_list_init(&seat->keyboard_shortcuts_inhibitors);
 585→
 586→	sway_input_method_relay_init(seat, &seat->im_relay);
 587→
 588→	bool first = wl_list_empty(&server.input->seats);
 589→	wl_list_insert(&server.input->seats, &seat->link);
 590→
 591→	if (!first) {
 592→		// Since this is not the first seat, attempt to set initial focus
 593→		struct sway_seat *current_seat = input_manager_current_seat();
 594→		struct sway_node *current_focus =
 595→			seat_get_focus_inactive(current_seat, &root->node);
 596→		seat_set_focus(seat, current_focus);
 597→	}
 598→
 599→	seatop_begin_default(seat);
 600→
 601→	return seat;
 602→}
