 650→/**
 651→ * Get the name of the built-in output, if any. Returns NULL if there isn't
 652→ * exactly one built-in output.
 653→ */
 654→static const char *get_builtin_output_name(void) {
 655→	const char *match = NULL;
 656→	for (int i = 0; i < root->outputs->length; ++i) {
 657→		struct sway_output *output = root->outputs->items[i];
 658→		const char *name = output->wlr_output->name;
 659→		if (has_prefix(name, "eDP-") || has_prefix(name, "LVDS-") ||
 660→				has_prefix(name, "DSI-")) {
 661→			if (match != NULL) {
 662→				return NULL;
 663→			}
 664→			match = name;
 665→		}
 666→	}
 667→	return match;
 668→}
