 979→void seat_configure_xcursor(struct sway_seat *seat) {
 980→	unsigned cursor_size = 24;
 981→	const char *cursor_theme = NULL;
 982→
 983→	const struct seat_config *seat_config = seat_get_config(seat);
 984→	if (!seat_config) {
 985→		seat_config = seat_get_config_by_name("*");
 986→	}
 987→	if (seat_config) {
 988→		cursor_size = seat_config->xcursor_theme.size;
 989→		cursor_theme = seat_config->xcursor_theme.name;
 990→	}
 991→
 992→	if (seat == input_manager_get_default_seat()) {
 993→		char cursor_size_fmt[16];
 994→		snprintf(cursor_size_fmt, sizeof(cursor_size_fmt), "%u", cursor_size);
 995→		setenv("XCURSOR_SIZE", cursor_size_fmt, 1);
 996→		if (cursor_theme != NULL) {
 997→			setenv("XCURSOR_THEME", cursor_theme, 1);
 998→		}
 999→
1000→#if WLR_HAS_XWAYLAND
1001→		if (server.xwayland.wlr_xwayland && (!server.xwayland.xcursor_manager ||
1002→				!xcursor_manager_is_named(server.xwayland.xcursor_manager,
1003→					cursor_theme) ||
1004→				server.xwayland.xcursor_manager->size != cursor_size)) {
1005→
1006→			wlr_xcursor_manager_destroy(server.xwayland.xcursor_manager);
1007→
1008→			server.xwayland.xcursor_manager =
1009→				wlr_xcursor_manager_create(cursor_theme, cursor_size);
1010→			sway_assert(server.xwayland.xcursor_manager,
1011→						"Cannot create XCursor manager for theme");
1012→
1013→			wlr_xcursor_manager_load(server.xwayland.xcursor_manager, 1);
1014→			struct wlr_xcursor *xcursor = wlr_xcursor_manager_get_xcursor(
1015→				server.xwayland.xcursor_manager, "default", 1);
1016→			if (xcursor != NULL) {
1017→				struct wlr_xcursor_image *image = xcursor->images[0];
1018→				struct wlr_buffer *buffer = wlr_xcursor_image_get_buffer(image);
1019→				wlr_xwayland_set_cursor(
1020→					server.xwayland.wlr_xwayland, buffer,
1021→					image->hotspot_x, image->hotspot_y);
1022→			}
1023→		}
1024→#endif
1025→	}
1026→
1027→	/* Create xcursor manager if we don't have one already, or if the
1028→	 * theme has changed */
1029→	if (!seat->cursor->xcursor_manager ||
1030→			!xcursor_manager_is_named(
1031→				seat->cursor->xcursor_manager, cursor_theme) ||
1032→			seat->cursor->xcursor_manager->size != cursor_size) {
1033→
1034→		wlr_xcursor_manager_destroy(seat->cursor->xcursor_manager);
1035→		seat->cursor->xcursor_manager =
1036→			wlr_xcursor_manager_create(cursor_theme, cursor_size);
1037→		if (!seat->cursor->xcursor_manager) {
1038→			sway_log(SWAY_ERROR,
1039→				"Cannot create XCursor manager for theme '%s'", cursor_theme);
1040→		}
1041→
1042→
1043→		for (int i = 0; i < root->outputs->length; ++i) {
1044→			struct sway_output *sway_output = root->outputs->items[i];
1045→			struct wlr_output *output = sway_output->wlr_output;
1046→			bool result =
1047→				wlr_xcursor_manager_load(seat->cursor->xcursor_manager,
1048→					output->scale);
1049→			if (!result) {
1050→				sway_log(SWAY_ERROR,
1051→					"Cannot load xcursor theme for output '%s' with scale %f",
1052→					output->name, output->scale);
1053→			}
1054→		}
1055→
1056→		// Reset the cursor so that we apply it to outputs that just appeared
1057→		cursor_set_image(seat->cursor, NULL, NULL);
1058→		cursor_set_image(seat->cursor, "default", NULL);
1059→		wlr_cursor_warp(seat->cursor->cursor, NULL, seat->cursor->cursor->x,
1060→			seat->cursor->cursor->y);
1061→	}
1062→}
