1115→void seat_set_raw_focus(struct sway_seat *seat, struct sway_node *node) {
1116→	struct sway_seat_node *seat_node = seat_node_from_node(seat, node);
1117→	wl_list_remove(&seat_node->link);
1118→	wl_list_insert(&seat->focus_stack, &seat_node->link);
1119→	node_set_dirty(node);
1120→
1121→	// If focusing a scratchpad container that is fullscreen global, parent
1122→	// will be NULL
1123→	struct sway_node *parent = node_get_parent(node);
1124→	if (parent) {
1125→		node_set_dirty(parent);
1126→	}
1127→}
1128→
1129→static void seat_set_workspace_focus(struct sway_seat *seat, struct sway_node *node) {
1130→	struct sway_node *last_focus = seat_get_focus(seat);
1131→	if (last_focus == node) {
1132→		return;
1133→	}
1134→
1135→	struct sway_workspace *last_workspace = seat_get_focused_workspace(seat);
1136→
1137→	if (node == NULL) {
1138→		// Close any popups on the old focus
1139→		if (node_is_view(last_focus)) {
1140→			view_close_popups(last_focus->sway_container->view);
1141→		}
1142→		seat_send_unfocus(last_focus, seat);
1143→		sway_input_method_relay_set_focus(&seat->im_relay, NULL);
1144→		seat->has_focus = false;
1145→		return;
1146→	}
1147→
1148→	struct sway_workspace *new_workspace = node->type == N_WORKSPACE ?
1149→		node->sway_workspace : node->sway_container->pending.workspace;
1150→	struct sway_container *container = node->type == N_CONTAINER ?
1151→		node->sway_container : NULL;
1152→
1153→	// Deny setting focus to a view which is hidden by a fullscreen container or global
1154→	if (container && container_obstructing_fullscreen_container(container)) {
1155→		return;
1156→	}
1157→
1158→	// Deny setting focus to a workspace node when using fullscreen global
1159→	if (root->fullscreen_global && !container && new_workspace) {
1160→		return;
1161→	}
1162→
1163→	struct sway_output *new_output =
1164→		new_workspace ? new_workspace->output : NULL;
1165→
1166→	if (last_workspace != new_workspace && new_output) {
1167→		node_set_dirty(&new_output->node);
1168→	}
1169→
1170→	// find new output's old workspace, which might have to be removed if empty
1171→	struct sway_workspace *new_output_last_ws =
1172→		new_output ? output_get_active_workspace(new_output) : NULL;
1173→
1174→	// Unfocus the previous focus
1175→	if (last_focus) {
1176→		seat_send_unfocus(last_focus, seat);
1177→		node_set_dirty(last_focus);
1178→		struct sway_node *parent = node_get_parent(last_focus);
1179→		if (parent) {
1180→			node_set_dirty(parent);
1181→		}
1182→	}
1183→
1184→	// Put the container parents on the focus stack, then the workspace, then
1185→	// the focused container.
1186→	if (container) {
1187→		struct sway_container *parent = container->pending.parent;
1188→		while (parent) {
1189→			seat_set_raw_focus(seat, &parent->node);
1190→			parent = parent->pending.parent;
1191→		}
1192→	}
1193→	if (new_workspace) {
1194→		seat_set_raw_focus(seat, &new_workspace->node);
1195→	}
1196→	if (container) {
1197→		seat_set_raw_focus(seat, &container->node);
1198→		seat_send_focus(&container->node, seat);
1199→	}
1200→
1201→	// emit ipc events
1202→	set_workspace(seat, new_workspace);
1203→	if (container && container->view) {
1204→		ipc_event_window(container, "focus");
1205→	}
1206→
1207→	// Move sticky containers to new workspace
1208→	if (new_workspace && new_output_last_ws
1209→			&& new_workspace != new_output_last_ws) {
1210→		for (int i = 0; i < new_output_last_ws->floating->length; ++i) {
1211→			struct sway_container *floater =
1212→				new_output_last_ws->floating->items[i];
1213→			if (container_is_sticky(floater)) {
1214→				container_detach(floater);
1215→				workspace_add_floating(new_workspace, floater);
1216→				--i;
1217→			}
1218→		}
1219→	}
1220→
1221→	// Close any popups on the old focus
1222→	if (last_focus && node_is_view(last_focus)) {
1223→		view_close_popups(last_focus->sway_container->view);
1224→	}
1225→
1226→	// If urgent, either unset the urgency or start a timer to unset it
1227→	if (container && container->view && view_is_urgent(container->view) &&
1228→			!container->view->urgent_timer) {
1229→		struct sway_view *view = container->view;
1230→		if (last_workspace && last_workspace != new_workspace &&
1231→				config->urgent_timeout > 0) {
1232→			view->urgent_timer = wl_event_loop_add_timer(server.wl_event_loop,
1233→					handle_urgent_timeout, view);
1234→			if (view->urgent_timer) {
1235→				wl_event_source_timer_update(view->urgent_timer,
1236→						config->urgent_timeout);
1237→			} else {
1238→				sway_log_errno(SWAY_ERROR, "Unable to create urgency timer");
1239→				handle_urgent_timeout(view);
1240→			}
1241→		} else {
1242→			view_set_urgent(view, false);
1243→		}
1244→	}
1245→
1246→	if (new_output_last_ws) {
1247→		workspace_consider_destroy(new_output_last_ws);
1248→	}
1249→	if (last_workspace && last_workspace != new_output_last_ws) {
1250→		workspace_consider_destroy(last_workspace);
1251→	}
1252→
1253→	seat->has_focus = true;
1254→
1255→	if (config->smart_gaps && new_workspace) {
1256→		// When smart gaps is on, gaps may change when the focus changes so
1257→		// the workspace needs to be arranged
1258→		arrange_workspace(new_workspace);
1259→	}
1260→}
