1262→void seat_set_focus(struct sway_seat *seat, struct sway_node *node) {
1263→	// Prevents the layer from losing focus if it has keyboard exclusivity
1264→	if (seat->has_exclusive_layer) {
1265→		struct wlr_layer_surface_v1 *layer = seat->focused_layer;
1266→		seat_set_focus_layer(seat, NULL);
1267→		seat_set_workspace_focus(seat, node);
1268→		seat_set_focus_layer(seat, layer);
1269→	} else if (seat->focused_layer) {
1270→		seat_set_focus_layer(seat, NULL);
1271→		seat_set_workspace_focus(seat, node);
1272→	} else {
1273→		seat_set_workspace_focus(seat, node);
1274→	}
1275→	if (server.session_lock.lock) {
1276→		seat_set_focus_surface(seat, server.session_lock.lock->focused, false);
1277→	}
1278→}
