1293→		struct sway_node *focus = seat_get_focus(seat);
1294→		seat_send_unfocus(focus, seat);
1295→		seat->has_focus = false;
1296→	}
1297→
1298→	if (surface) {
1299→		seat_keyboard_notify_enter(seat, surface);
1300→	} else {
1301→		wlr_seat_keyboard_notify_clear_focus(seat->wlr_seat);
1302→	}
