1308→void seat_set_focus_layer(struct sway_seat *seat,
1309→		struct wlr_layer_surface_v1 *layer) {
1310→	if (!layer && seat->focused_layer) {
1311→		seat->focused_layer = NULL;
1312→		struct sway_node *previous = seat_get_focus_inactive(seat, &root->node);
1313→		if (previous) {
1314→			// Hack to get seat to re-focus the return value of get_focus
1315→			seat_set_focus(seat, NULL);
1316→			seat_set_focus(seat, previous);
1317→		}
1318→		return;
1319→	} else if (!layer) {
1320→		return;
1321→	}
1322→	assert(layer->surface->mapped);
1323→	if (layer->current.layer >= ZWLR_LAYER_SHELL_V1_LAYER_TOP &&
1324→			layer->current.keyboard_interactive
1325→			== ZWLR_LAYER_SURFACE_V1_KEYBOARD_INTERACTIVITY_EXCLUSIVE) {
1326→		seat->has_exclusive_layer = true;
1327→	}
1328→	if (seat->focused_layer == layer) {
1329→		return;
1330→	}
1331→	seat_set_focus_surface(seat, layer->surface, true);
1332→	seat->focused_layer = layer;
1333→}
