1335→void seat_unfocus_unless_client(struct sway_seat *seat, struct wl_client *client) {
1336→	if (seat->focused_layer) {
1337→		if (wl_resource_get_client(seat->focused_layer->resource) != client) {
1338→			seat_set_focus_layer(seat, NULL);
1339→		}
1340→	}
1341→	if (seat->has_focus) {
1342→		struct sway_node *focus = seat_get_focus(seat);
1343→		if (node_is_view(focus) && wl_resource_get_client(
1344→					focus->sway_container->view->surface->resource) != client) {
1345→			seat_set_focus(seat, NULL);
1346→		}
1347→	}
1348→	if (seat->wlr_seat->pointer_state.focused_client) {
1349→		if (seat->wlr_seat->pointer_state.focused_client->client != client) {
1350→			wlr_seat_pointer_notify_clear_focus(seat->wlr_seat);
1351→		}
1352→	}
1353→	struct timespec now;
1354→	clock_gettime(CLOCK_MONOTONIC, &now);
1355→	struct wlr_touch_point *point;
1356→	wl_list_for_each(point, &seat->wlr_seat->touch_state.touch_points, link) {
1357→		if (point->client->client != client) {
1358→			wlr_seat_touch_point_clear_focus(seat->wlr_seat,
1359→					now.tv_nsec / 1000, point->touch_id);
1360→		}
1361→	}
1362→}
