1364→struct sway_node *seat_get_focus_inactive(struct sway_seat *seat,
1365→		struct sway_node *node) {
1366→	if (node_is_view(node)) {
1367→		return node;
1368→	}
1369→	struct sway_seat_node *current;
1370→	wl_list_for_each(current, &seat->focus_stack, link) {
1371→		if (node_has_ancestor(current->node, node)) {
1372→			return current->node;
1373→		}
1374→	}
1375→	if (node->type == N_WORKSPACE) {
1376→		return node;
1377→	}
1378→	return NULL;
