1381→struct sway_container *seat_get_focus_inactive_tiling(struct sway_seat *seat,
1382→		struct sway_workspace *workspace) {
1383→	if (!workspace->tiling->length) {
1384→		return NULL;
1385→	}
1386→	struct sway_seat_node *current;
1387→	wl_list_for_each(current, &seat->focus_stack, link) {
1388→		struct sway_node *node = current->node;
1389→		if (node->type == N_CONTAINER &&
1390→				!container_is_floating_or_child(node->sway_container) &&
1391→				node->sway_container->pending.workspace == workspace) {
1392→			return node->sway_container;
1393→		}
1394→	}
1395→	return NULL;
1396→}
