1402→	}
1403→	struct sway_seat_node *current;
1404→	wl_list_for_each(current, &seat->focus_stack, link) {
1405→		struct sway_node *node = current->node;
1406→		if (node->type == N_CONTAINER &&
1407→				container_is_floating_or_child(node->sway_container) &&
1408→				node->sway_container->pending.workspace == workspace) {
1409→			return node->sway_container;
1410→		}
1411→	}
