1415→struct sway_node *seat_get_active_tiling_child(struct sway_seat *seat,
1416→		struct sway_node *parent) {
1417→	if (node_is_view(parent)) {
1418→		return parent;
1419→	}
1420→	struct sway_seat_node *current;
1421→	wl_list_for_each(current, &seat->focus_stack, link) {
1422→		struct sway_node *node = current->node;
1423→		if (node_get_parent(node) != parent) {
1424→			continue;
1425→		}
1426→		if (parent->type == N_WORKSPACE) {
1427→			// Only consider tiling children
1428→			struct sway_workspace *ws = parent->sway_workspace;
1429→			if (list_find(ws->tiling, node->sway_container) == -1) {
1430→				continue;
1431→			}
1432→		}
1433→		return node;
1434→	}
1435→	return NULL;
1436→}
