1449→struct sway_workspace *seat_get_focused_workspace(struct sway_seat *seat) {
1450→	struct sway_node *focus = seat_get_focus_inactive(seat, &root->node);
1451→	if (!focus) {
1452→		return NULL;
1453→	}
1454→	if (focus->type == N_CONTAINER) {
1455→		return focus->sway_container->pending.workspace;
1456→	}
1457→	if (focus->type == N_WORKSPACE) {
1458→		return focus->sway_workspace;
1459→	}
1460→	return NULL; // output doesn't have a workspace yet
1461→}
