1465→	wl_list_for_each(current, &seat->focus_stack, link) {
1466→		struct sway_node *node = current->node;
1467→		if (node->type == N_CONTAINER &&
1468→				node->sway_container->pending.workspace) {
1469→			return node->sway_container->pending.workspace;
1470→		} else if (node->type == N_WORKSPACE) {
1471→			return node->sway_workspace;
1472→		}
