1533→void seat_consider_warp_to_focus(struct sway_seat *seat) {
1534→	struct sway_node *focus = seat_get_focus(seat);
1535→	if (config->mouse_warping == WARP_NO || !focus) {
1536→		return;
1537→	}
1538→	if (config->mouse_warping == WARP_OUTPUT) {
1539→		struct sway_output *output = node_get_output(focus);
1540→		if (output) {
1541→			struct wlr_box box;
1542→			output_get_box(output, &box);
1543→			if (wlr_box_contains_point(&box,
1544→						seat->cursor->cursor->x, seat->cursor->cursor->y)) {
1545→				return;
1546→			}
1547→		}
1548→	}
1549→
1550→	if (focus->type == N_CONTAINER) {
1551→		cursor_warp_to_container(seat->cursor, focus->sway_container, false);
1552→	} else {
1553→		cursor_warp_to_workspace(seat->cursor, focus->sway_workspace);
1554→	}
1555→}
