 26→static void popup_handle_new_popup(struct wl_listener *listener, void *data) {
 27→	struct sway_xdg_popup *popup =
 28→		wl_container_of(listener, popup, new_popup);
 29→	struct wlr_xdg_popup *wlr_popup = data;
 30→	popup_create(wlr_popup, popup->view, popup->xdg_surface_tree, popup->image_capture_tree);
