 33→static void popup_handle_destroy(struct wl_listener *listener, void *data) {
 34→	struct sway_xdg_popup *popup = wl_container_of(listener, popup, destroy);
 35→
 36→	wl_list_remove(&popup->new_popup.link);
 37→	wl_list_remove(&popup->destroy.link);
 38→	wl_list_remove(&popup->surface_commit.link);
 39→	wl_list_remove(&popup->reposition.link);
 40→	wlr_scene_node_destroy(&popup->scene_tree->node);
 41→	free(popup);
 42→}
