 44→static void popup_unconstrain(struct sway_xdg_popup *popup) {
 45→	struct sway_view *view = popup->view;
 46→	struct wlr_xdg_popup *wlr_popup = popup->wlr_xdg_popup;
 47→
 48→	struct sway_workspace *workspace = view->container->pending.workspace;
 49→	if (!workspace) {
 50→		// is null if in the scratchpad
 51→		return;
 52→	}
 53→
 54→	struct sway_output *output = workspace->output;
 55→
 56→	// the output box expressed in the coordinate system of the toplevel parent
 57→	// of the popup
 58→	struct wlr_box output_toplevel_sx_box = {
 59→		.x = output->lx - view->container->pending.content_x + view->geometry.x,
 60→		.y = output->ly - view->container->pending.content_y + view->geometry.y,
 61→		.width = output->width,
 62→		.height = output->height,
 63→	};
 64→
 65→	wlr_xdg_popup_unconstrain_from_box(wlr_popup, &output_toplevel_sx_box);
 66→}
