 68→static void popup_handle_surface_commit(struct wl_listener *listener, void *data) {
 69→	struct sway_xdg_popup *popup = wl_container_of(listener, popup, surface_commit);
 70→	if (popup->wlr_xdg_popup->base->initial_commit) {
 71→		popup_unconstrain(popup);
 72→	}
 73→}
