 80→static struct sway_xdg_popup *popup_create(struct wlr_xdg_popup *wlr_popup,
 81→		struct sway_view *view, struct wlr_scene_tree *parent,
 82→		struct wlr_scene_tree *image_capture_parent) {
 83→	struct wlr_xdg_surface *xdg_surface = wlr_popup->base;
 84→
 85→	struct sway_xdg_popup *popup = calloc(1, sizeof(struct sway_xdg_popup));
 86→	if (!popup) {
 87→		return NULL;
 88→	}
 89→
 90→	popup->wlr_xdg_popup = wlr_popup;
 91→	popup->view = view;
 92→
 93→	popup->scene_tree = wlr_scene_tree_create(parent);
 94→	if (!popup->scene_tree) {
 95→		free(popup);
 96→		return NULL;
 97→	}
 98→
 99→	popup->xdg_surface_tree = wlr_scene_xdg_surface_create(
100→		popup->scene_tree, xdg_surface);
101→	if (!popup->xdg_surface_tree) {
102→		wlr_scene_node_destroy(&popup->scene_tree->node);
103→		free(popup);
104→		return NULL;
105→	}
106→
107→	popup->desc.relative = &view->content_tree->node;
108→	popup->desc.view = view;
109→
110→	if (!scene_descriptor_assign(&popup->scene_tree->node,
111→			SWAY_SCENE_DESC_POPUP, &popup->desc)) {
112→		sway_log(SWAY_ERROR, "Failed to allocate a popup scene descriptor");
113→		wlr_scene_node_destroy(&popup->scene_tree->node);
114→		free(popup);
115→		return NULL;
116→	}
117→
118→	popup->image_capture_tree = wlr_scene_xdg_surface_create(image_capture_parent, xdg_surface);
119→	if (popup->image_capture_tree == NULL) {
120→		return NULL;
121→	}
122→
123→	popup->wlr_xdg_popup = xdg_surface->popup;
124→	struct sway_xdg_shell_view *shell_view =
125→		wl_container_of(view, shell_view, view);
126→	xdg_surface->data = shell_view;
127→
128→	wl_signal_add(&xdg_surface->surface->events.commit, &popup->surface_commit);
129→	popup->surface_commit.notify = popup_handle_surface_commit;
130→	wl_signal_add(&xdg_surface->events.new_popup, &popup->new_popup);
131→	popup->new_popup.notify = popup_handle_new_popup;
132→	wl_signal_add(&wlr_popup->events.reposition, &popup->reposition);
133→	popup->reposition.notify = popup_handle_reposition;
134→	wl_signal_add(&wlr_popup->events.destroy, &popup->destroy);
135→	popup->destroy.notify = popup_handle_destroy;
136→
137→	return popup;
138→}
