195→static void set_tiled(struct sway_view *view, bool tiled) {
196→	if (xdg_shell_view_from_view(view) == NULL) {
197→		return;
198→	}
199→	if (wl_resource_get_version(view->wlr_xdg_toplevel->resource) >=
200→			XDG_TOPLEVEL_STATE_TILED_LEFT_SINCE_VERSION) {
201→		enum wlr_edges edges = WLR_EDGE_NONE;
202→		if (tiled) {
203→			edges = WLR_EDGE_LEFT | WLR_EDGE_RIGHT | WLR_EDGE_TOP |
204→					WLR_EDGE_BOTTOM;
205→		}
206→		wlr_xdg_toplevel_set_tiled(view->wlr_xdg_toplevel, edges);
207→	} else {
208→		// The version is too low for the tiled state; configure as maximized instead
209→		// to stop the client from drawing decorations outside of the toplevel geometry.
210→		wlr_xdg_toplevel_set_maximized(view->wlr_xdg_toplevel, tiled);
211→	}
212→}
