291→static void handle_commit(struct wl_listener *listener, void *data) {
292→	struct sway_xdg_shell_view *xdg_shell_view =
293→		wl_container_of(listener, xdg_shell_view, commit);
294→	struct sway_view *view = &xdg_shell_view->view;
295→	struct wlr_xdg_surface *xdg_surface = view->wlr_xdg_toplevel->base;
296→
297→	if (xdg_surface->initial_commit) {
298→		if (view->xdg_decoration != NULL) {
299→			set_xdg_decoration_mode(view->xdg_decoration);
300→		}
301→		// XXX: https://github.com/swaywm/sway/issues/2176
302→		wlr_xdg_surface_schedule_configure(xdg_surface);
303→		wlr_xdg_toplevel_set_wm_capabilities(view->wlr_xdg_toplevel,
304→			WLR_XDG_TOPLEVEL_WM_CAPABILITIES_FULLSCREEN);
305→		// TODO: wlr_xdg_toplevel_set_bounds()
306→		return;
307→	}
308→
309→	if (!xdg_surface->surface->mapped) {
310→		return;
311→	}
312→
313→	struct wlr_box *new_geo = &xdg_surface->geometry;
314→	bool new_size = new_geo->width != view->geometry.width ||
315→			new_geo->height != view->geometry.height ||
316→			new_geo->x != view->geometry.x ||
317→			new_geo->y != view->geometry.y;
318→
319→	if (new_size) {
320→		// The client changed its surface size in this commit. For floating
321→		// containers, we resize the container to match. For tiling containers,
322→		// we only recenter the surface.
323→		memcpy(&view->geometry, new_geo, sizeof(struct wlr_box));
324→		if (container_is_floating(view->container)) {
325→			view_update_size(view);
326→			// Only set the toplevel size the current container actually has a size.
327→			if (view->container->current.width) {
328→				wlr_xdg_toplevel_set_size(view->wlr_xdg_toplevel, view->geometry.width,
329→					view->geometry.height);
330→			}
331→			transaction_commit_dirty_client();
332→		}
333→
334→		view_center_and_clip_surface(view);
335→	}
336→
337→	if (view->container->node.instruction) {
338→		bool successful = transaction_notify_view_ready_by_serial(view,
339→				xdg_surface->current.configure_serial);
340→
341→		// If we saved the view and this commit isn't what we're looking for
342→		// that means the user will never actually see the buffers submitted to
343→		// us here. Just send frame done events to these surfaces so they can
344→		// commit another time for us.
345→		if (view->saved_surface_tree && !successful) {
346→			view_send_frame_done(view);
347→		}
348→	}
349→}
