395→static void handle_request_fullscreen(struct wl_listener *listener, void *data) {
396→	struct sway_xdg_shell_view *xdg_shell_view =
397→		wl_container_of(listener, xdg_shell_view, request_fullscreen);
398→	struct wlr_xdg_toplevel *toplevel = xdg_shell_view->view.wlr_xdg_toplevel;
399→	struct sway_view *view = &xdg_shell_view->view;
400→
401→	if (!toplevel->base->surface->mapped) {
402→		return;
403→	}
404→
405→	struct sway_container *container = view->container;
406→	struct wlr_xdg_toplevel_requested *req = &toplevel->requested;
407→	if (req->fullscreen && req->fullscreen_output && req->fullscreen_output->data) {
408→		struct sway_output *output = req->fullscreen_output->data;
409→		struct sway_workspace *ws = output_get_active_workspace(output);
410→		if (ws && !container_is_scratchpad_hidden(container) &&
411→				container->pending.workspace != ws) {
412→			if (container_is_floating(container)) {
413→				workspace_add_floating(ws, container);
414→			} else {
415→				container = workspace_add_tiling(ws, container);
416→			}
417→		}
418→	}
419→
420→	container_set_fullscreen(container, req->fullscreen);
421→
422→	arrange_root();
423→	transaction_commit_dirty();
424→}
