475→static void handle_map(struct wl_listener *listener, void *data) {
476→	struct sway_xdg_shell_view *xdg_shell_view =
477→		wl_container_of(listener, xdg_shell_view, map);
478→	struct sway_view *view = &xdg_shell_view->view;
479→	struct wlr_xdg_toplevel *toplevel = view->wlr_xdg_toplevel;
480→
481→	view->natural_width = toplevel->base->geometry.width;
482→	view->natural_height = toplevel->base->geometry.height;
483→
484→	bool csd = false;
485→
486→	if (view->xdg_decoration) {
487→		enum wlr_xdg_toplevel_decoration_v1_mode mode =
488→			view->xdg_decoration->wlr_xdg_decoration->requested_mode;
489→		csd = mode == WLR_XDG_TOPLEVEL_DECORATION_V1_MODE_CLIENT_SIDE;
490→	} else {
491→		struct sway_server_decoration *deco =
492→				decoration_from_surface(toplevel->base->surface);
493→		csd = !deco || deco->wlr_server_decoration->mode ==
494→			WLR_SERVER_DECORATION_MANAGER_MODE_CLIENT;
495→	}
496→
497→	view_map(view, toplevel->base->surface,
498→		toplevel->requested.fullscreen,
499→		toplevel->requested.fullscreen_output,
500→		csd);
501→
502→	transaction_commit_dirty();
503→
504→	xdg_shell_view->new_popup.notify = handle_new_popup;
505→	wl_signal_add(&toplevel->base->events.new_popup,
506→		&xdg_shell_view->new_popup);
507→
508→	xdg_shell_view->request_maximize.notify = handle_request_maximize;
509→	wl_signal_add(&toplevel->events.request_maximize,
510→			&xdg_shell_view->request_maximize);
511→
512→	xdg_shell_view->request_fullscreen.notify = handle_request_fullscreen;
513→	wl_signal_add(&toplevel->events.request_fullscreen,
514→			&xdg_shell_view->request_fullscreen);
515→
516→	xdg_shell_view->request_move.notify = handle_request_move;
517→	wl_signal_add(&toplevel->events.request_move,
518→			&xdg_shell_view->request_move);
519→
520→	xdg_shell_view->request_resize.notify = handle_request_resize;
521→	wl_signal_add(&toplevel->events.request_resize,
522→			&xdg_shell_view->request_resize);
523→
524→	xdg_shell_view->set_title.notify = handle_set_title;
525→	wl_signal_add(&toplevel->events.set_title,
526→			&xdg_shell_view->set_title);
527→
528→	xdg_shell_view->set_app_id.notify = handle_set_app_id;
529→	wl_signal_add(&toplevel->events.set_app_id,
530→			&xdg_shell_view->set_app_id);
531→}
