533→static void handle_destroy(struct wl_listener *listener, void *data) {
534→	struct sway_xdg_shell_view *xdg_shell_view =
535→		wl_container_of(listener, xdg_shell_view, destroy);
536→	struct sway_view *view = &xdg_shell_view->view;
