556→void handle_xdg_shell_toplevel(struct wl_listener *listener, void *data) {
557→	struct wlr_xdg_toplevel *xdg_toplevel = data;
558→
559→	sway_log(SWAY_DEBUG, "New xdg_shell toplevel title='%s' app_id='%s'",
560→		xdg_toplevel->title, xdg_toplevel->app_id);
561→	wlr_xdg_surface_ping(xdg_toplevel->base);
562→
563→	struct sway_xdg_shell_view *xdg_shell_view =
564→		calloc(1, sizeof(struct sway_xdg_shell_view));
565→	if (!sway_assert(xdg_shell_view, "Failed to allocate view")) {
566→		return;
567→	}
568→
569→	if (!view_init(&xdg_shell_view->view, SWAY_VIEW_XDG_SHELL, &view_impl)) {
570→		free(xdg_shell_view);
571→		return;
572→	}
573→	xdg_shell_view->view.wlr_xdg_toplevel = xdg_toplevel;
574→
575→	xdg_shell_view->map.notify = handle_map;
576→	wl_signal_add(&xdg_toplevel->base->surface->events.map, &xdg_shell_view->map);
577→
578→	xdg_shell_view->unmap.notify = handle_unmap;
579→	wl_signal_add(&xdg_toplevel->base->surface->events.unmap, &xdg_shell_view->unmap);
580→
581→	xdg_shell_view->commit.notify = handle_commit;
582→	wl_signal_add(&xdg_toplevel->base->surface->events.commit,
583→		&xdg_shell_view->commit);
584→
585→	xdg_shell_view->destroy.notify = handle_destroy;
586→	wl_signal_add(&xdg_toplevel->events.destroy, &xdg_shell_view->destroy);
587→
