  31→/*-----------------------------------------\
  32→ * Functions shared by multiple callbacks  /
  33→ *---------------------------------------*/
  34→
  35→/**
  36→ * Determine if the edge of the given container is on the edge of the
  37→ * workspace/output.
  38→ */
  39→static bool edge_is_external(struct sway_container *cont, enum wlr_edges edge) {
  40→	enum sway_container_layout layout = L_NONE;
  41→	switch (edge) {
  42→	case WLR_EDGE_TOP:
  43→	case WLR_EDGE_BOTTOM:
  44→		layout = L_VERT;
  45→		break;
  46→	case WLR_EDGE_LEFT:
  47→	case WLR_EDGE_RIGHT:
  48→		layout = L_HORIZ;
  49→		break;
  50→	case WLR_EDGE_NONE:
  51→		sway_assert(false, "Never reached");
  52→		return false;
  53→	}
  54→
  55→	// Iterate the parents until we find one with the layout we want,
  56→	// then check if the child has siblings between it and the edge.
  57→	while (cont) {
  58→		if (container_parent_layout(cont) == layout) {
  59→			list_t *siblings = container_get_siblings(cont);
  60→			if (!siblings) {
  61→				return false;
  62→			}
  63→			int index = list_find(siblings, cont);
  64→			if (index > 0 && (edge == WLR_EDGE_LEFT || edge == WLR_EDGE_TOP)) {
  65→				return false;
  66→			}
  67→			if (index < siblings->length - 1 &&
  68→					(edge == WLR_EDGE_RIGHT || edge == WLR_EDGE_BOTTOM)) {
  69→				return false;
  70→			}
  71→		}
  72→		cont = cont->pending.parent;
  73→	}
  74→	return true;
  75→}
  76→
  77→static enum wlr_edges find_edge(struct sway_container *cont,
  78→		struct wlr_surface *surface, struct sway_cursor *cursor) {
  79→	if (!cont->view || (surface && cont->view->surface != surface)) {
  80→		return WLR_EDGE_NONE;
  81→	}
  82→	if (cont->pending.border == B_NONE || !cont->pending.border_thickness ||
  83→			cont->pending.border == B_CSD) {
  84→		return WLR_EDGE_NONE;
  85→	}
  86→	if (cont->pending.fullscreen_mode) {
  87→		return WLR_EDGE_NONE;
  88→	}
  89→
  90→	enum wlr_edges edge = 0;
  91→	if (cursor->cursor->x < cont->pending.x + cont->pending.border_thickness) {
  92→		edge |= WLR_EDGE_LEFT;
  93→	}
  94→	if (cursor->cursor->y < cont->pending.y + cont->pending.border_thickness) {
  95→		edge |= WLR_EDGE_TOP;
  96→	}
  97→	if (cursor->cursor->x >= cont->pending.x + cont->pending.width - cont->pending.border_thickness) {
  98→		edge |= WLR_EDGE_RIGHT;
  99→	}
 100→	if (cursor->cursor->y >= cont->pending.y + cont->pending.height - cont->pending.border_thickness) {
 101→		edge |= WLR_EDGE_BOTTOM;
 102→	}
 103→
 104→	return edge;
 105→}
 106→
 107→/**
 108→ * If the cursor is over a _resizable_ edge, return the edge.
 109→ * Edges that can't be resized are edges of the workspace.
 110→ */
 111→enum wlr_edges find_resize_edge(struct sway_container *cont,
 112→		struct wlr_surface *surface, struct sway_cursor *cursor) {
 113→	enum wlr_edges edge = find_edge(cont, surface, cursor);
 114→	if (edge && !container_is_floating(cont) && edge_is_external(cont, edge)) {
 115→		return WLR_EDGE_NONE;
 116→	}
 117→	return edge;
 118→}
