 120→/**
 121→ * Return the mouse binding which matches modifier, click location, release,
 122→ * and pressed button state, otherwise return null.
 123→ */
 124→static struct sway_binding* get_active_mouse_binding(
 125→		struct seatop_default_event *e, list_t *bindings, uint32_t modifiers,
 126→		bool release, bool on_titlebar, bool on_border, bool on_content,
 127→		bool on_workspace, const char *identifier) {
 128→	uint32_t click_region =
 129→			((on_titlebar || on_workspace) ? BINDING_TITLEBAR : 0) |
 130→			((on_border || on_workspace) ? BINDING_BORDER : 0) |
 131→			((on_content || on_workspace) ? BINDING_CONTENTS : 0);
 132→
 133→	struct sway_binding *current = NULL;
 134→	for (int i = 0; i < bindings->length; ++i) {
 135→		struct sway_binding *binding = bindings->items[i];
 136→		if (modifiers ^ binding->modifiers ||
 137→				e->pressed_button_count != (size_t)binding->keys->length ||
 138→				release != (binding->flags & BINDING_RELEASE) ||
 139→				!(click_region & binding->flags) ||
 140→				(on_workspace &&
 141→				 (click_region & binding->flags) != click_region) ||
 142→				(strcmp(binding->input, identifier) != 0 &&
 143→				 strcmp(binding->input, "*") != 0)) {
 144→			continue;
 145→		}
 146→
 147→		bool match = true;
 148→		for (size_t j = 0; j < e->pressed_button_count; j++) {
 149→			uint32_t key = *(uint32_t *)binding->keys->items[j];
 150→			if (key != e->pressed_buttons[j]) {
 151→				match = false;
 152→				break;
 153→			}
 154→		}
 155→		if (!match) {
 156→			continue;
 157→		}
 158→
 159→		if (!current || strcmp(current->input, "*") == 0) {
 160→			current = binding;
 161→			if (strcmp(current->input, identifier) == 0) {
 162→				// If a binding is found for the exact input, quit searching
 163→				break;
 164→			}
 165→		}
 166→	}
 167→	return current;
 168→}
