 170→/**
 171→ * Remove a button (and duplicates) from the sorted list of currently pressed
 172→ * buttons.
 173→ */
 174→static void state_erase_button(struct seatop_default_event *e,
 175→		uint32_t button) {
 176→	size_t j = 0;
 177→	for (size_t i = 0; i < e->pressed_button_count; ++i) {
 178→		if (i > j) {
 179→			e->pressed_buttons[j] = e->pressed_buttons[i];
 180→		}
 181→		if (e->pressed_buttons[i] != button) {
 182→			++j;
 183→		}
 184→	}
 185→	while (e->pressed_button_count > j) {
 186→		--e->pressed_button_count;
 187→		e->pressed_buttons[e->pressed_button_count] = 0;
 188→	}
 189→}
 190→
 191→/**
 192→ * Add a button to the sorted list of currently pressed buttons, if there
 193→ * is space.
 194→ */
 195→static void state_add_button(struct seatop_default_event *e, uint32_t button) {
 196→	if (e->pressed_button_count >= SWAY_CURSOR_PRESSED_BUTTONS_CAP) {
 197→		return;
 198→	}
 199→	size_t i = 0;
 200→	while (i < e->pressed_button_count && e->pressed_buttons[i] < button) {
 201→		++i;
 202→	}
 203→	size_t j = e->pressed_button_count;
 204→	while (j > i) {
 205→		e->pressed_buttons[j] = e->pressed_buttons[j - 1];
 206→		--j;
 207→	}
 208→	e->pressed_buttons[i] = button;
 209→	e->pressed_button_count++;
 210→}
