 216→static void handle_tablet_tool_tip(struct sway_seat *seat,
 217→		struct sway_tablet_tool *tool, uint32_t time_msec,
 218→		enum wlr_tablet_tool_tip_state state) {
 219→	if (state == WLR_TABLET_TOOL_TIP_UP) {
 220→		wlr_tablet_v2_tablet_tool_notify_up(tool->tablet_v2_tool);
 221→		return;
 222→	}
 223→
 224→	struct sway_cursor *cursor = seat->cursor;
 225→	struct wlr_surface *surface = NULL;
 226→	double sx, sy;
 227→	struct sway_node *node = node_at_coords(seat,
 228→		cursor->cursor->x, cursor->cursor->y, &surface, &sx, &sy);
 229→
 230→	if (!sway_assert(surface,
 231→			"Expected null-surface tablet input to route through pointer emulation")) {
 232→		return;
 233→	}
 234→
 235→	struct sway_container *cont = node && node->type == N_CONTAINER ?
 236→		node->sway_container : NULL;
 237→
 238→	struct wlr_layer_surface_v1 *layer;
 239→#if WLR_HAS_XWAYLAND
 240→	struct wlr_xwayland_surface *xsurface;
 241→#endif
 242→	if ((layer = wlr_layer_surface_v1_try_from_wlr_surface(surface)) &&
 243→			layer->current.keyboard_interactive) {
 244→		// Handle tapping a layer surface
 245→		seat_set_focus_layer(seat, layer);
 246→		transaction_commit_dirty();
 247→	} else if (cont) {
 248→		bool is_floating_or_child = container_is_floating_or_child(cont);
 249→		bool is_fullscreen_or_child = container_is_fullscreen_or_child(cont);
 250→		struct wlr_keyboard *keyboard = wlr_seat_get_keyboard(seat->wlr_seat);
 251→		bool mod_pressed = keyboard &&
 252→			(wlr_keyboard_get_modifiers(keyboard) & config->floating_mod);
 253→
 254→		// Handle beginning floating move
 255→		if (is_floating_or_child && !is_fullscreen_or_child && mod_pressed) {
 256→			seat_set_focus_container(seat,
 257→				seat_get_focus_inactive_view(seat, &cont->node));
 258→			seatop_begin_move_floating(seat, container_toplevel_ancestor(cont));
 259→			return;
 260→		}
 261→
 262→		// Handle moving a tiling container
 263→		if (config->tiling_drag && mod_pressed && !is_floating_or_child &&
 264→				cont->pending.fullscreen_mode == FULLSCREEN_NONE) {
 265→			seatop_begin_move_tiling(seat, cont);
 266→			return;
 267→		}
 268→
 269→		// Handle tapping on a container surface
 270→		seat_set_focus_container(seat, cont);
 271→		seatop_begin_down(seat, node->sway_container, sx, sy);
 272→	}
 273→#if WLR_HAS_XWAYLAND
 274→	// Handle tapping on an xwayland unmanaged view
 275→	else if ((xsurface = wlr_xwayland_surface_try_from_wlr_surface(surface)) &&
 276→			xsurface->override_redirect &&
 277→			wlr_xwayland_surface_override_redirect_wants_focus(xsurface)) {
 278→		struct wlr_xwayland *xwayland = server.xwayland.wlr_xwayland;
 279→		wlr_xwayland_set_seat(xwayland, seat->wlr_seat);
 280→		seat_set_focus_surface(seat, xsurface->surface, false);
 281→		transaction_commit_dirty();
 282→	}
 283→#endif
 284→
 285→	wlr_tablet_v2_tablet_tool_notify_down(tool->tablet_v2_tool);
 286→	wlr_tablet_tool_v2_start_implicit_grab(tool->tablet_v2_tool);
 287→}
