 292→
 293→static bool trigger_pointer_button_binding(struct sway_seat *seat,
 294→		struct wlr_input_device *device, uint32_t button,
 295→		enum wl_pointer_button_state state, uint32_t modifiers,
 296→		bool on_titlebar, bool on_border, bool on_contents, bool on_workspace) {
 297→	// We can reach this for non-pointer devices if we're currently emulating
 298→	// pointer input for one. Emulated input should not trigger bindings. The
 299→	// device can be NULL if this is synthetic (e.g. swaymsg-generated) input.
 300→	if (device && device->type != WLR_INPUT_DEVICE_POINTER) {
 301→		return false;
 302→	}
 303→
 304→	struct seatop_default_event *e = seat->seatop_data;
 305→
 306→	char *device_identifier = device ? input_device_get_identifier(device)
 307→		: strdup("*");
 308→	struct sway_binding *binding = NULL;
 309→	if (state == WL_POINTER_BUTTON_STATE_PRESSED) {
 310→		state_add_button(e, button);
 311→		binding = get_active_mouse_binding(e,
 312→			config->current_mode->mouse_bindings, modifiers, false,
 313→			on_titlebar, on_border, on_contents, on_workspace,
 314→			device_identifier);
 315→	} else {
 316→		binding = get_active_mouse_binding(e,
 317→			config->current_mode->mouse_bindings, modifiers, true,
 318→			on_titlebar, on_border, on_contents, on_workspace,
 319→			device_identifier);
 320→		state_erase_button(e, button);
 321→	}
 322→
 323→	free(device_identifier);
 324→	if (binding) {
 325→		seat_execute_command(seat, binding);
 326→		return true;
 327→	}
 328→
 329→	return false;
 330→}
 331→
 332→static void handle_button(struct sway_seat *seat, uint32_t time_msec,
 333→		struct wlr_input_device *device, uint32_t button,
 334→		enum wl_pointer_button_state state) {
 335→	struct sway_cursor *cursor = seat->cursor;
 336→
 337→	// Determine what's under the cursor
 338→	struct wlr_surface *surface = NULL;
 339→	double sx, sy;
 340→	struct sway_node *node = node_at_coords(seat,
 341→			cursor->cursor->x, cursor->cursor->y, &surface, &sx, &sy);
 342→
 343→	struct sway_container *cont = node && node->type == N_CONTAINER ?
 344→		node->sway_container : NULL;
 345→	bool is_floating = cont && container_is_floating(cont);
 346→	bool is_floating_or_child = cont && container_is_floating_or_child(cont);
 347→	bool is_fullscreen_or_child = cont && container_is_fullscreen_or_child(cont);
 348→	enum wlr_edges edge = cont ? find_edge(cont, surface, cursor) : WLR_EDGE_NONE;
 349→	enum wlr_edges resize_edge = cont && edge ?
 350→		find_resize_edge(cont, surface, cursor) : WLR_EDGE_NONE;
 351→	bool on_border = edge != WLR_EDGE_NONE;
 352→	bool on_contents = cont && !on_border && surface;
 353→	bool on_workspace = node && node->type == N_WORKSPACE;
 354→	bool on_titlebar = cont && !on_border && !surface;
 355→
 356→	struct wlr_keyboard *keyboard = wlr_seat_get_keyboard(seat->wlr_seat);
 357→	uint32_t modifiers = keyboard ? wlr_keyboard_get_modifiers(keyboard) : 0;
 358→
 359→	bool mod_pressed = modifiers & config->floating_mod;
 360→	uint32_t mod_move_btn = config->floating_mod_inverse ? BTN_RIGHT : BTN_LEFT;
 361→	uint32_t mod_resize_btn = config->floating_mod_inverse ? BTN_LEFT : BTN_RIGHT;
 362→	bool mod_move_btn_pressed = mod_pressed && button == mod_move_btn;
 363→	bool mod_resize_btn_pressed = mod_pressed && button == mod_resize_btn;
 364→	bool titlebar_left_btn_pressed = on_titlebar && button == BTN_LEFT;
 365→
 366→	// Handle mouse bindings
 367→	if (trigger_pointer_button_binding(seat, device, button, state, modifiers,
 368→			on_titlebar, on_border, on_contents, on_workspace)) {
 369→		return;
 370→	}
 371→
 372→	// Handle clicking an empty workspace
 373→	if (node && node->type == N_WORKSPACE) {
 374→		if (state == WL_POINTER_BUTTON_STATE_PRESSED) {
 375→			seat_set_focus(seat, node);
 376→			transaction_commit_dirty();
 377→		}
 378→		seat_pointer_notify_button(seat, time_msec, button, state);
 379→		return;
 380→	}
 381→
 382→	// Handle clicking a layer surface and its popups/subsurfaces
 383→	struct wlr_layer_surface_v1 *layer = NULL;
 384→	if ((layer = toplevel_layer_surface_from_surface(surface))) {
 385→		if (layer->current.keyboard_interactive) {
 386→			seat_set_focus_layer(seat, layer);
 387→			transaction_commit_dirty();
 388→		}
 389→		if (state == WL_POINTER_BUTTON_STATE_PRESSED) {
 390→			seatop_begin_down_on_surface(seat, surface, sx, sy);
 391→		}
 392→		seat_pointer_notify_button(seat, time_msec, button, state);
 393→		return;
 394→	}
 395→
 396→	// Handle tiling resize via border
 397→	if (cont && resize_edge && button == BTN_LEFT &&
 398→			state == WL_POINTER_BUTTON_STATE_PRESSED && !is_floating) {
 399→		// If a resize is triggered on a tabbed or stacked container, change
 400→		// focus to the tab which already had inactive focus -- otherwise, we'd
 401→		// change the active tab when the user probably just wanted to resize.
 402→		struct sway_container *cont_to_focus = cont;
 403→		enum sway_container_layout layout = container_parent_layout(cont);
 404→		if (layout == L_TABBED || layout == L_STACKED) {
 405→			cont_to_focus = seat_get_focus_inactive_view(seat, &cont->pending.parent->node);
 406→		}
 407→
 408→		seat_set_focus_container(seat, cont_to_focus);
 409→		seatop_begin_resize_tiling(seat, cont, edge);
 410→		return;
 411→	}
 412→
 413→	// Handle tiling resize via mod
 414→	if (cont && !is_floating_or_child && mod_pressed && mod_resize_btn_pressed &&
 415→			state == WL_POINTER_BUTTON_STATE_PRESSED) {
 416→		edge = 0;
 417→		edge |= cursor->cursor->x > cont->pending.x + cont->pending.width / 2 ?
 418→			WLR_EDGE_RIGHT : WLR_EDGE_LEFT;
 419→		edge |= cursor->cursor->y > cont->pending.y + cont->pending.height / 2 ?
 420→			WLR_EDGE_BOTTOM : WLR_EDGE_TOP;
 421→
 422→		const char *image = NULL;
 423→		if (edge == (WLR_EDGE_LEFT | WLR_EDGE_TOP)) {
 424→			image = "nw-resize";
 425→		} else if (edge == (WLR_EDGE_TOP | WLR_EDGE_RIGHT)) {
 426→			image = "ne-resize";
 427→		} else if (edge == (WLR_EDGE_RIGHT | WLR_EDGE_BOTTOM)) {
 428→			image = "se-resize";
 429→		} else if (edge == (WLR_EDGE_BOTTOM | WLR_EDGE_LEFT)) {
 430→			image = "sw-resize";
 431→		}
 432→		cursor_set_image(seat->cursor, image, NULL);
 433→		seat_set_focus_container(seat, cont);
 434→		seatop_begin_resize_tiling(seat, cont, edge);
 435→		return;
 436→	}
 437→
 438→	// Handle changing focus when clicking on a container
 439→	if (cont && state == WL_POINTER_BUTTON_STATE_PRESSED) {
 440→		// Default case: focus the container that was just clicked.
 441→		node = &cont->node;
 442→
 443→		// If the container is a tab/stacked container and the click happened
 444→		// on a tab, switch to the tab. If the tab contents were already
 445→		// focused, focus the tab container itself. If the tab container was
 446→		// already focused, cycle back to focusing the tab contents.
 447→		if (on_titlebar) {
 448→			struct sway_container *focus = seat_get_focused_container(seat);
 449→			if (focus == cont || !container_has_ancestor(focus, cont)) {
 450→				node = seat_get_focus_inactive(seat, &cont->node);
 451→			}
 452→		}
 453→
 454→		seat_set_focus(seat, node);
 455→		transaction_commit_dirty();
 456→	}
 457→
 458→	// Handle beginning floating move
 459→	if (cont && is_floating_or_child && !is_fullscreen_or_child &&
 460→			state == WL_POINTER_BUTTON_STATE_PRESSED &&
 461→			(mod_move_btn_pressed || titlebar_left_btn_pressed)) {
 462→		seatop_begin_move_floating(seat, container_toplevel_ancestor(cont));
 463→		return;
 464→	}
 465→
 466→	// Handle beginning floating resize
 467→	if (cont && is_floating_or_child && !is_fullscreen_or_child &&
 468→			state == WL_POINTER_BUTTON_STATE_PRESSED) {
 469→		// Via border
 470→		if (button == BTN_LEFT && resize_edge != WLR_EDGE_NONE) {
 471→			seat_set_focus_container(seat, cont);
 472→			seatop_begin_resize_floating(seat, cont, resize_edge);
 473→			return;
 474→		}
 475→
 476→		// Via mod+click
 477→		if (mod_resize_btn_pressed) {
 478→			struct sway_container *floater = container_toplevel_ancestor(cont);
 479→			edge = 0;
 480→			edge |= cursor->cursor->x > floater->pending.x + floater->pending.width / 2 ?
 481→				WLR_EDGE_RIGHT : WLR_EDGE_LEFT;
 482→			edge |= cursor->cursor->y > floater->pending.y + floater->pending.height / 2 ?
 483→				WLR_EDGE_BOTTOM : WLR_EDGE_TOP;
 484→			seat_set_focus_container(seat, floater);
 485→			seatop_begin_resize_floating(seat, floater, edge);
 486→			return;
 487→		}
 488→	}
 489→
 490→	// Handle moving a tiling container
 491→	if (config->tiling_drag && (mod_move_btn_pressed || titlebar_left_btn_pressed) &&
 492→			state == WL_POINTER_BUTTON_STATE_PRESSED && !is_floating_or_child &&
 493→			cont && cont->pending.fullscreen_mode == FULLSCREEN_NONE) {
 494→		// If moving a container by its title bar, use a threshold for the drag
 495→		if (!mod_pressed && config->tiling_drag_threshold > 0) {
 496→			seatop_begin_move_tiling_threshold(seat, cont);
 497→		} else {
 498→			seatop_begin_move_tiling(seat, cont);
 499→		}
 500→		return;
 501→	}
 502→
 503→	// Handle mousedown on a container surface
 504→	if (surface && cont && state == WL_POINTER_BUTTON_STATE_PRESSED) {
 505→		seatop_begin_down(seat, cont, sx, sy);
 506→		seat_pointer_notify_button(seat, time_msec, button, WL_POINTER_BUTTON_STATE_PRESSED);
 507→		return;
 508→	}
 509→
 510→	// Handle clicking a container surface or decorations
 511→	if (cont && state == WL_POINTER_BUTTON_STATE_PRESSED) {
 512→		seat_pointer_notify_button(seat, time_msec, button, state);
 513→		return;
 514→	}
 515→
 516→#if WLR_HAS_XWAYLAND
 517→	// Handle clicking on xwayland unmanaged view
 518→	struct wlr_xwayland_surface *xsurface;
 519→	if (surface &&
 520→			(xsurface = wlr_xwayland_surface_try_from_wlr_surface(surface)) &&
 521→			xsurface->override_redirect &&
 522→			wlr_xwayland_surface_override_redirect_wants_focus(xsurface)) {
 523→		struct wlr_xwayland *xwayland = server.xwayland.wlr_xwayland;
 524→		wlr_xwayland_set_seat(xwayland, seat->wlr_seat);
 525→		seat_set_focus_surface(seat, xsurface->surface, false);
 526→		transaction_commit_dirty();
 527→		seat_pointer_notify_button(seat, time_msec, button, state);
 528→	}
 529→#endif
 530→
 531→	seat_pointer_notify_button(seat, time_msec, button, state);
 532→}
