 538→static void check_focus_follows_mouse(struct sway_seat *seat,
 539→		struct seatop_default_event *e, struct sway_node *hovered_node) {
 540→	struct sway_node *focus = seat_get_focus(seat);
 541→
 542→	// This is the case if a layer-shell surface is hovered.
 543→	// If it's on another output, focus the active workspace there.
 544→	if (!hovered_node) {
 545→		struct wlr_output *wlr_output = wlr_output_layout_output_at(
 546→				root->output_layout, seat->cursor->cursor->x, seat->cursor->cursor->y);
 547→		if (wlr_output == NULL) {
 548→			return;
 549→		}
 550→
 551→		struct wlr_surface *surface = NULL;
 552→		double sx, sy;
 553→		node_at_coords(seat, seat->cursor->cursor->x, seat->cursor->cursor->y,
 554→				&surface, &sx, &sy);
 555→
 556→		// Focus topmost layer surface
 557→		struct wlr_layer_surface_v1 *layer = NULL;
 558→		if ((layer = toplevel_layer_surface_from_surface(surface)) &&
 559→				layer->current.keyboard_interactive) {
 560→			seat_set_focus_layer(seat, layer);
 561→			transaction_commit_dirty();
 562→			return;
 563→		}
 564→
 565→		struct sway_output *hovered_output = wlr_output->data;
 566→		if (focus && hovered_output != node_get_output(focus)) {
 567→			struct sway_workspace *ws = output_get_active_workspace(hovered_output);
 568→			seat_set_focus(seat, &ws->node);
 569→			transaction_commit_dirty();
 570→		}
 571→		return;
 572→	}
 573→
 574→	// If a workspace node is hovered (eg. in the gap area), only set focus if
 575→	// the workspace is on a different output to the previous focus.
 576→	if (focus && hovered_node->type == N_WORKSPACE) {
 577→		struct sway_output *focused_output = node_get_output(focus);
 578→		struct sway_output *hovered_output = node_get_output(hovered_node);
 579→		if (hovered_output != focused_output) {
 580→			seat_set_focus(seat, seat_get_focus_inactive(seat, hovered_node));
 581→			transaction_commit_dirty();
 582→		}
 583→		return;
 584→	}
 585→
 586→	// This is where we handle the common case. We don't want to focus inactive
 587→	// tabs, hence the view_is_visible check.
 588→	if (node_is_view(hovered_node) &&
 589→			view_is_visible(hovered_node->sway_container->view)) {
 590→		// e->previous_node is the node which the cursor was over previously.
 591→		// If focus_follows_mouse is yes and the cursor got over the view due
 592→		// to, say, a workspace switch, we don't want to set the focus.
 593→		// But if focus_follows_mouse is "always", we do.
 594→		if (hovered_node != e->previous_node ||
 595→				config->focus_follows_mouse == FOLLOWS_ALWAYS) {
 596→			seat_set_focus(seat, hovered_node);
 597→			transaction_commit_dirty();
 598→		}
 599→	}
 600→}
