 602→static void handle_pointer_motion(struct sway_seat *seat, uint32_t time_msec) {
 603→	struct seatop_default_event *e = seat->seatop_data;
 604→	struct sway_cursor *cursor = seat->cursor;
 605→
 606→	struct wlr_surface *surface = NULL;
 607→	double sx, sy;
 608→	struct sway_node *node = node_at_coords(seat,
 609→			cursor->cursor->x, cursor->cursor->y, &surface, &sx, &sy);
 610→
 611→	if (config->focus_follows_mouse != FOLLOWS_NO) {
 612→		check_focus_follows_mouse(seat, e, node);
 613→	}
 614→
 615→	if (surface) {
 616→		if (seat_is_input_allowed(seat, surface)) {
 617→			wlr_seat_pointer_notify_enter(seat->wlr_seat, surface, sx, sy);
 618→			wlr_seat_pointer_notify_motion(seat->wlr_seat, time_msec, sx, sy);
 619→		}
 620→	} else {
 621→		cursor_update_image(cursor, node);
 622→		wlr_seat_pointer_notify_clear_focus(seat->wlr_seat);
 623→	}
 624→
 625→	drag_icons_update_position(seat);
 626→
 627→	e->previous_node = node;
 628→}
