 660→static void handle_touch_down(struct sway_seat *seat,
 661→		struct wlr_touch_down_event *event, double lx, double ly) {
 662→	struct wlr_surface *surface = NULL;
 663→	struct wlr_seat *wlr_seat = seat->wlr_seat;
 664→	struct sway_cursor *cursor = seat->cursor;
 665→	double sx, sy;
 666→	node_at_coords(seat, seat->touch_x, seat->touch_y, &surface, &sx, &sy);
 667→
 668→	if (surface && wlr_surface_accepts_touch(surface, wlr_seat)) {
 669→		if (seat_is_input_allowed(seat, surface)) {
 670→			cursor->simulating_pointer_from_touch = false;
 671→			seatop_begin_touch_down(seat, surface, event, sx, sy, lx, ly);
 672→		}
 673→	} else if (!cursor->simulating_pointer_from_touch &&
 674→			(!surface || seat_is_input_allowed(seat, surface))) {
 675→		// Fallback to cursor simulation.
 676→		// The pointer_touch_id state is needed, so drags are not aborted when over
 677→		// a surface supporting touch and multi touch events don't interfere.
 678→		cursor->simulating_pointer_from_touch = true;
 679→		cursor->pointer_touch_id = seat->touch_id;
 680→		double dx, dy;
 681→		dx = seat->touch_x - cursor->cursor->x;
 682→		dy = seat->touch_y - cursor->cursor->y;
 683→		pointer_motion(cursor, event->time_msec, &event->touch->base, dx, dy,
 684→				dx, dy);
 685→		dispatch_cursor_button(cursor, &event->touch->base, event->time_msec,
 686→				BTN_LEFT, WL_POINTER_BUTTON_STATE_PRESSED);
 687→	}
 688→}
