 691→ * Functions used by handle_pointer_axis  /
 692→ *--------------------------------------*/
 693→
 694→static uint32_t wl_axis_to_button(struct wlr_pointer_axis_event *event) {
 695→	switch (event->orientation) {
 696→	case WL_POINTER_AXIS_VERTICAL_SCROLL:
 697→		return event->delta < 0 ? SWAY_SCROLL_UP : SWAY_SCROLL_DOWN;
 698→	case WL_POINTER_AXIS_HORIZONTAL_SCROLL:
 699→		return event->delta < 0 ? SWAY_SCROLL_LEFT : SWAY_SCROLL_RIGHT;
 700→	default:
 701→		sway_log(SWAY_DEBUG, "Unknown axis orientation");
 702→		return 0;
 703→	}
 704→}
 705→
 706→static void handle_pointer_axis(struct sway_seat *seat,
 707→		struct wlr_pointer_axis_event *event) {
 708→	struct sway_input_device *input_device =
 709→		event->pointer ? event->pointer->base.data : NULL;
 710→	struct input_config *ic =
 711→		input_device ? input_device_get_config(input_device) : NULL;
 712→	struct sway_cursor *cursor = seat->cursor;
 713→	struct seatop_default_event *e = seat->seatop_data;
 714→
 715→	// Determine what's under the cursor
 716→	struct wlr_surface *surface = NULL;
 717→	double sx, sy;
 718→	struct sway_node *node = node_at_coords(seat,
 719→			cursor->cursor->x, cursor->cursor->y, &surface, &sx, &sy);
 720→	struct sway_container *cont = node && node->type == N_CONTAINER ?
 721→		node->sway_container : NULL;
 722→	enum wlr_edges edge = cont ? find_edge(cont, surface, cursor) : WLR_EDGE_NONE;
 723→	bool on_border = edge != WLR_EDGE_NONE;
 724→	bool on_titlebar = cont && !on_border && !surface;
 725→	bool on_titlebar_border = cont && on_border &&
 726→		cursor->cursor->y < cont->pending.content_y;
 727→	bool on_contents = cont && !on_border && surface;
 728→	bool on_workspace = node && node->type == N_WORKSPACE;
 729→	float scroll_factor =
 730→		(ic == NULL || ic->scroll_factor == FLT_MIN) ? 1.0f : ic->scroll_factor;
 731→
 732→	bool handled = false;
 733→
 734→	// Gather information needed for mouse bindings
 735→	struct wlr_keyboard *keyboard = wlr_seat_get_keyboard(seat->wlr_seat);
 736→	uint32_t modifiers = keyboard ? wlr_keyboard_get_modifiers(keyboard) : 0;
 737→	struct wlr_input_device *device =
 738→		input_device ? input_device->wlr_device : NULL;
 739→	char *dev_id = device ? input_device_get_identifier(device) : strdup("*");
 740→	uint32_t button = wl_axis_to_button(event);
 741→
 742→	// Handle mouse bindings - x11 mouse buttons 4-7 - press event
 743→	struct sway_binding *binding = NULL;
 744→	state_add_button(e, button);
 745→	binding = get_active_mouse_binding(e, config->current_mode->mouse_bindings,
 746→			modifiers, false, on_titlebar, on_border, on_contents, on_workspace,
 747→			dev_id);
 748→	if (binding) {
 749→		seat_execute_command(seat, binding);
 750→		handled = true;
 751→	}
 752→
 753→	// Scrolling on a tabbed or stacked title bar (handled as press event)
 754→	if (!handled && (on_titlebar || on_titlebar_border)) {
 755→		struct sway_node *new_focus;
 756→		enum sway_container_layout layout = container_parent_layout(cont);
 757→		if (layout == L_TABBED || layout == L_STACKED) {
 758→			struct sway_node *tabcontainer = node_get_parent(node);
 759→			struct sway_node *active =
 760→				seat_get_active_tiling_child(seat, tabcontainer);
 761→			list_t *siblings = container_get_siblings(cont);
 762→			int desired = list_find(siblings, active->sway_container) +
 763→				roundf(scroll_factor * event->delta_discrete / WLR_POINTER_AXIS_DISCRETE_STEP);
 764→			if (desired < 0) {
 765→				desired = 0;
 766→			} else if (desired >= siblings->length) {
 767→				desired = siblings->length - 1;
 768→			}
 769→
 770→			struct sway_container *new_sibling_con = siblings->items[desired];
 771→			struct sway_node *new_sibling = &new_sibling_con->node;
 772→			// Use the focused child of the tabbed/stacked container, not the
 773→			// container the user scrolled on.
 774→			new_focus = seat_get_focus_inactive(seat, new_sibling);
 775→		} else {
 776→			new_focus = seat_get_focus_inactive(seat, &cont->node);
 777→		}
 778→
 779→		seat_set_focus(seat, new_focus);
 780→		transaction_commit_dirty();
 781→		handled = true;
 782→	}
 783→
 784→	// Handle mouse bindings - x11 mouse buttons 4-7 - release event
 785→	binding = get_active_mouse_binding(e, config->current_mode->mouse_bindings,
 786→			modifiers, true, on_titlebar, on_border, on_contents, on_workspace,
 787→			dev_id);
 788→	state_erase_button(e, button);
 789→	if (binding) {
 790→		seat_execute_command(seat, binding);
 791→		handled = true;
 792→	}
 793→	free(dev_id);
 794→
 795→	if (!handled) {
 796→		wlr_seat_pointer_notify_axis(cursor->seat->wlr_seat, event->time_msec,
 797→			event->orientation, scroll_factor * event->delta,
 798→			roundf(scroll_factor * event->delta_discrete), event->source,
 799→			event->relative_direction);
 800→	}
 801→}
