 803→/*------------------------------------\
 804→ * Functions used by gesture support  /
 805→ *----------------------------------*/
 806→
 807→/**
 808→ * Check gesture binding for a specific gesture type and finger count.
 809→ * Returns true if binding is present, false otherwise
 810→ */
 811→static bool gesture_binding_check(list_t *bindings, enum gesture_type type,
 812→		uint8_t fingers, struct sway_input_device *device) {
 813→	char *input =
 814→		device ? input_device_get_identifier(device->wlr_device) : strdup("*");
 815→
 816→	for (int i = 0; i < bindings->length; ++i) {
 817→		struct sway_gesture_binding *binding = bindings->items[i];
 818→
 819→		// Check type and finger count
 820→		if (!gesture_check(&binding->gesture, type, fingers)) {
 821→			continue;
 822→		}
 823→
 824→		// Check that input matches
 825→		if (strcmp(binding->input, "*") != 0 &&
 826→			strcmp(binding->input, input) != 0) {
 827→			continue;
 828→		}
 829→
 830→		free(input);
 831→
 832→		return true;
 833→	}
 834→
 835→	free(input);
 836→
 837→	return false;
 838→}
 839→
 840→/**
 841→ * Return the gesture binding which matches gesture type, finger count
 842→ * and direction, otherwise return null.
 843→ */
 844→static struct sway_gesture_binding* gesture_binding_match(
 845→		list_t *bindings, struct gesture *gesture, const char *input) {
 846→	struct sway_gesture_binding *current = NULL;
 847→
 848→	// Find best matching binding
 849→	for (int i = 0; i < bindings->length; ++i) {
 850→		struct sway_gesture_binding *binding = bindings->items[i];
 851→		bool exact = binding->flags & BINDING_EXACT;
 852→
 853→		// Check gesture matching
 854→		if (!gesture_match(&binding->gesture, gesture, exact)) {
 855→			continue;
 856→		}
 857→
 858→		// Check input matching
 859→		if (strcmp(binding->input, "*") != 0 &&
 860→				strcmp(binding->input, input) != 0) {
 861→			continue;
 862→		}
 863→
 864→		// If we already have a match ...
 865→		if (current) {
 866→			// ... check if input matching is equivalent
 867→			if (strcmp(current->input, binding->input) == 0) {
 868→
 869→				// ... - do not override an exact binding
 870→				if (!exact && current->flags & BINDING_EXACT) {
 871→					continue;
 872→				}
 873→
 874→				// ... - and ensure direction matching is better or equal
 875→				if (gesture_compare(&current->gesture, &binding->gesture) > 0) {
 876→					continue;
 877→				}
 878→			} else if (strcmp(binding->input, "*") == 0) {
 879→				// ... do not accept worse input match
 880→				continue;
 881→			}
 882→		}
 883→
 884→		// Accept newer or better match
 885→		current = binding;
 886→
 887→		// If exact binding and input is found, quit search
 888→		if (strcmp(current->input, input) == 0 &&
 889→				gesture_compare(&current->gesture, gesture) == 0) {
 890→			break;
 891→		}
 892→	} // for all gesture bindings
 893→
 894→	return current;
 895→}
 896→
 897→// Wrapper around gesture_tracker_end to use tracker with sway bindings
 898→static struct sway_gesture_binding* gesture_tracker_end_and_match(
 899→		struct gesture_tracker *tracker, struct sway_input_device* device) {
 900→	// Determine name of input that received gesture
 901→	char *input = device
 902→		? input_device_get_identifier(device->wlr_device)
 903→		: strdup("*");
 904→
 905→	// Match tracking result to binding
 906→	struct gesture *gesture = gesture_tracker_end(tracker);
 907→	struct sway_gesture_binding *binding = gesture_binding_match(
 908→			config->current_mode->gesture_bindings, gesture, input);
 909→	free(gesture);
 910→	free(input);
 911→
 912→	return binding;
 913→}
 914→
 915→// Small wrapper around seat_execute_command to work on gesture bindings
 916→static void gesture_binding_execute(struct sway_seat *seat,
 917→		struct sway_gesture_binding *binding) {
 918→	struct sway_binding *dummy_binding =
 919→		calloc(1, sizeof(struct sway_binding));
 920→	dummy_binding->type = BINDING_GESTURE;
 921→	dummy_binding->command = binding->command;
 922→
 923→	char *description = gesture_to_string(&binding->gesture);
 924→	sway_log(SWAY_DEBUG, "executing gesture binding: %s", description);
 925→	free(description);
 926→
 927→	seat_execute_command(seat, dummy_binding);
 928→
 929→	free(dummy_binding);
 930→}
