 932→static void handle_hold_begin(struct sway_seat *seat,
 933→		struct wlr_pointer_hold_begin_event *event) {
 934→	// Start tracking gesture if there is a matching binding ...
 935→	struct sway_input_device *device =
 936→		event->pointer ? event->pointer->base.data : NULL;
 937→	list_t *bindings = config->current_mode->gesture_bindings;
 938→	if (gesture_binding_check(bindings, GESTURE_TYPE_HOLD, event->fingers, device)) {
 939→		struct seatop_default_event *seatop = seat->seatop_data;
 940→		gesture_tracker_begin(&seatop->gestures, GESTURE_TYPE_HOLD, event->fingers);
 941→	} else {
 942→		// ... otherwise forward to client
 943→		struct sway_cursor *cursor = seat->cursor;
 944→		wlr_pointer_gestures_v1_send_hold_begin(
 945→			server.input->pointer_gestures, cursor->seat->wlr_seat,
 946→			event->time_msec, event->fingers);
 947→	}
 948→}
 949→
 950→static void handle_hold_end(struct sway_seat *seat,
 951→		struct wlr_pointer_hold_end_event *event) {
 952→	// Ensure that gesture is being tracked and was not cancelled
 953→	struct seatop_default_event *seatop = seat->seatop_data;
 954→	if (!gesture_tracker_check(&seatop->gestures, GESTURE_TYPE_HOLD)) {
 955→		struct sway_cursor *cursor = seat->cursor;
 956→		wlr_pointer_gestures_v1_send_hold_end(
 957→			server.input->pointer_gestures, cursor->seat->wlr_seat,
 958→			event->time_msec, event->cancelled);
 959→		return;
 960→	}
 961→	if (event->cancelled) {
 962→		gesture_tracker_cancel(&seatop->gestures);
 963→		return;
 964→	}
 965→
 966→	// End gesture tracking and execute matched binding
 967→	struct sway_input_device *device =
 968→		event->pointer ? event->pointer->base.data : NULL;
 969→	struct sway_gesture_binding *binding = gesture_tracker_end_and_match(
 970→		&seatop->gestures, device);
 971→
 972→	if (binding) {
 973→		gesture_binding_execute(seat, binding);
 974→	}
 975→}
