		/* Check drawin-specific button array (AwesomeWM-compatible two-stage emission) */
		if (luaA_drawin_button_check(drawin, rel_x, rel_y, event->button,
		                             CLEANMASK(mods), true)) {
			return;
		}

		/* Fall back to global button check */
