421→/** Put client on top of the stack.
422→ * \param c The client to raise.
423→ */
424→static inline void
425→client_raise(client_t *c)
426→{
427→    client_t *tc = c;
428→    int counter = 0;
429→    lua_State *L;  /* C90: declare all variables at top */
430→
431→    /* Find number of transient layers. */
432→    for(counter = 0; tc->transient_for; counter++)
433→        tc = tc->transient_for;
434→
435→    /* Push them in reverse order. */
436→    for(; counter > 0; counter--)
437→    {
438→        tc = c;
439→        for(int i = 0; i < counter; i++)
440→            tc = tc->transient_for;
441→        stack_client_append(tc);
442→    }
443→
444→    /* Push c on top of the stack. */
445→    stack_client_append(c);
446→
447→    /* Notify the listeners */
448→    L = globalconf_get_lua_State();
449→    luaA_object_push(L, c);
450→    luaA_object_emit_signal(L, -1, "raised", 0);
451→    lua_pop(L, 1);
452→}
