457→ */
458→static inline bool
459→client_isfixed(client_t *c)
460→{
461→    return (c->size_hints.flags & XCB_ICCCM_SIZE_HINT_P_MAX_SIZE
462→            && c->size_hints.flags & XCB_ICCCM_SIZE_HINT_P_MIN_SIZE
463→            && c->size_hints.max_width == c->size_hints.min_width
464→            && c->size_hints.max_height == c->size_hints.min_height
465→            && c->size_hints.max_width
466→            && c->size_hints.max_height
467→            && c->size_hints_honor);
