3876→apply_geometry_to_wlroots(Client *c)
3877→{
3878→	struct wlr_box clip;
3879→	int titlebar_left, titlebar_top;
3880→
3881→	if (!c->scene || !client_surface(c) || !client_surface(c)->mapped)
3882→		return;
3883→
3884→	/* Get titlebar sizes - they occupy space inside geometry.
3885→	 * When fullscreen, ignore titlebar sizes - surface should cover entire geometry. */
3886→	titlebar_left = c->fullscreen ? 0 : c->titlebar[CLIENT_TITLEBAR_LEFT].size;
3887→	titlebar_top = c->fullscreen ? 0 : c->titlebar[CLIENT_TITLEBAR_TOP].size;
3888→
3889→	/* Update scene-graph position and borders */
3890→	wlr_scene_node_set_position(&c->scene->node, c->geometry.x, c->geometry.y);
3891→	/* Offset scene_surface by titlebar sizes (titlebars occupy space in geometry) */
3892→	wlr_scene_node_set_position(&c->scene_surface->node, c->bw + titlebar_left, c->bw + titlebar_top);
3893→	wlr_scene_rect_set_size(c->border[0], c->geometry.width, c->bw);
3894→	wlr_scene_rect_set_size(c->border[1], c->geometry.width, c->bw);
3895→	wlr_scene_rect_set_size(c->border[2], c->bw, c->geometry.height - 2 * c->bw);
3896→	wlr_scene_rect_set_size(c->border[3], c->bw, c->geometry.height - 2 * c->bw);
3897→	wlr_scene_node_set_position(&c->border[1]->node, 0, c->geometry.height - c->bw);
3898→	wlr_scene_node_set_position(&c->border[2]->node, 0, c->bw);
3899→	wlr_scene_node_set_position(&c->border[3]->node, c->geometry.width - c->bw, c->bw);
3900→
3901→	/* Update shadow geometry */
3902→	if (c->shadow.tree) {
3903→		const shadow_config_t *shadow_config = shadow_get_effective_config(
3904→			c->shadow_config, false);
3905→		shadow_update_geometry(&c->shadow, shadow_config,
3906→			c->geometry.width, c->geometry.height);
3907→	}
3908→
3909→	/* Update titlebar positions - they depend on current geometry */
3910→	client_update_titlebar_positions(c);
3911→
3912→	/* Request size change from client (subtract borders AND titlebars from geometry)
3913→	 * CRITICAL: Only send configure if there's no pending resize waiting for client commit.
3914→	 * Without this check, we flood the client with configure events on every refresh cycle,
3915→	 * which crashes Firefox and other clients that can't handle rapid configure floods. */
3916→	if (!c->resize) {
3917→		if (c->fullscreen) {
3918→			/* Fullscreen: client gets full geometry minus borders only */
3919→			c->resize = client_set_size(c,
3920→					c->geometry.width - 2 * c->bw,
3921→					c->geometry.height - 2 * c->bw);
3922→		} else {
3923→			c->resize = client_set_size(c,
3924→					c->geometry.width - 2 * c->bw - titlebar_left - c->titlebar[CLIENT_TITLEBAR_RIGHT].size,
3925→					c->geometry.height - 2 * c->bw - titlebar_top - c->titlebar[CLIENT_TITLEBAR_BOTTOM].size);
3926→		}
3927→	}
3928→	client_get_clip(c, &clip);
3929→	wlr_scene_subsurface_tree_set_clip(&c->scene_surface->node, &clip);
3930→}
