3932→void
3933→resize(Client *c, struct wlr_box geo, int interact)
3934→{
3935→	struct wlr_box *bbox;
3936→
3937→	if (!c->mon || !client_surface(c)->mapped)
3938→		return;
3939→
3940→	bbox = interact ? &sgeom : &c->mon->w;
3941→
3942→	client_set_bounds(c, geo.width, geo.height);
3943→	c->geometry = geo;
3944→	applybounds(c, bbox);
3945→
3946→	/* Apply aspect ratio constraint (Wayland equivalent of ICCCM aspect hints).
3947→	 * Works on full geometry (including borders/titlebars) to match
3948→	 * the ratio captured from Lua (geo.width / geo.height). */
3949→	if (c->aspect_ratio > 0 && !c->fullscreen && !c->maximized) {
3950→		int w = c->geometry.width;
3951→		int h = c->geometry.height;
3952→		if (w > 0 && h > 0) {
3953→			double current = (double)w / h;
3954→			/* Tolerance: ~1 pixel to prevent rounding oscillation */
3955→			double epsilon = 1.5 / (double)h;
3956→			if (current - c->aspect_ratio > epsilon) {
3957→				c->geometry.width = (int)(h * c->aspect_ratio + 0.5);
3958→			} else if (c->aspect_ratio - current > epsilon) {
3959→				c->geometry.height = (int)(w / c->aspect_ratio + 0.5);
3960→			}
3961→		}
3962→	}
3963→
3964→	/* Apply to wlroots rendering */
3965→	apply_geometry_to_wlroots(c);
3966→
3967→	/* Emit signal for geometry change listeners */
3968→	luaA_emit_signal_global("client::property::geometry");
3969→}
