2721→/** Resize client window.
2722→ * The sizes given as parameters are with borders!
2723→ * \param c Client to resize.
2724→ * \param geometry New window geometry.
2725→ * \param honor_hints Use size hints.
2726→ * \return true if an actual resize occurred.
2727→ */
2728→bool
2729→client_resize(client_t *c, area_t geometry, bool honor_hints)
2730→{
2731→    if (honor_hints) {
2732→        /* We could get integer underflows in client_remove_titlebar_geometry()
2733→         * without these checks here.
2734→         */
2735→        if(geometry.width < c->titlebar[CLIENT_TITLEBAR_LEFT].size + c->titlebar[CLIENT_TITLEBAR_RIGHT].size) {
2736→            return false;
2737→        }
2738→        if(geometry.height < c->titlebar[CLIENT_TITLEBAR_TOP].size + c->titlebar[CLIENT_TITLEBAR_BOTTOM].size) {
2739→            return false;
2740→        }
2741→        geometry = client_apply_size_hints(c, geometry);
2742→    }
2743→
2744→    /* Apply aspect ratio constraint (Wayland equivalent of ICCCM aspect hints).
2745→     * Works on full geometry to match the ratio captured from Lua. */
2746→    if (c->aspect_ratio > 0 && !c->fullscreen && !c->maximized) {
2747→        int w = geometry.width;
2748→        int h = geometry.height;
2749→        if (w > 0 && h > 0) {
2750→            double current = (double)w / h;
2751→            double epsilon = 1.5 / (double)h;
2752→            if (current - c->aspect_ratio > epsilon) {
2753→                geometry.width = (int)(h * c->aspect_ratio + 0.5);
2754→            } else if (c->aspect_ratio - current > epsilon) {
2755→                geometry.height = (int)(w / c->aspect_ratio + 0.5);
2756→            }
2757→        }
2758→    }
2759→
2760→    if(geometry.width < c->titlebar[CLIENT_TITLEBAR_LEFT].size + c->titlebar[CLIENT_TITLEBAR_RIGHT].size) {
2761→        return false;
2762→    }
2763→    if(geometry.height < c->titlebar[CLIENT_TITLEBAR_TOP].size + c->titlebar[CLIENT_TITLEBAR_BOTTOM].size) {
2764→        return false;
2765→    }
2766→
2767→    if(geometry.width == 0 || geometry.height == 0) {
2768→        return false;
2769→    }
2770→
2771→    if(!AREA_EQUAL(c->geometry, geometry))
2772→    {
2773→        client_resize_do(c, geometry);
2774→
2775→        return true;
2776→    }
2777→
2778→    return false;
2779→}
