2553→{
2554→    int32_t minw = 0, minh = 0;
2555→    int32_t basew = 0, baseh = 0, real_basew = 0, real_baseh = 0;
2556→
2557→    if (c->fullscreen)
2558→        return geometry;
2559→
2560→    /* Size hints are applied to the window without any decoration */
2561→    client_remove_titlebar_geometry(c, &geometry);
2562→
2563→    if(c->size_hints.flags & XCB_ICCCM_SIZE_HINT_BASE_SIZE)
2564→    {
2565→        basew = c->size_hints.base_width;
2566→        baseh = c->size_hints.base_height;
2567→        real_basew = basew;
2568→        real_baseh = baseh;
2569→    }
2570→    else if(c->size_hints.flags & XCB_ICCCM_SIZE_HINT_P_MIN_SIZE)
2571→    {
2572→        /* base size is substituted with min size if not specified */
2573→        basew = c->size_hints.min_width;
2574→        baseh = c->size_hints.min_height;
2575→    }
2576→
2577→    if(c->size_hints.flags & XCB_ICCCM_SIZE_HINT_P_MIN_SIZE)
2578→    {
2579→        minw = c->size_hints.min_width;
2580→        minh = c->size_hints.min_height;
2581→    }
2582→    else if(c->size_hints.flags & XCB_ICCCM_SIZE_HINT_BASE_SIZE)
2583→    {
2584→        /* min size is substituted with base size if not specified */
2585→        minw = c->size_hints.base_width;
2586→        minh = c->size_hints.base_height;
2587→    }
2588→
2589→    /* Handle the size aspect ratio */
2590→    if(c->size_hints.flags & XCB_ICCCM_SIZE_HINT_P_ASPECT
2591→            && c->size_hints.min_aspect_den > 0
2592→            && c->size_hints.max_aspect_den > 0
2593→            && geometry.height > real_baseh
2594→            && geometry.width > real_basew)
2595→    {
2596→        /* ICCCM mandates:
2597→         * If a base size is provided along with the aspect ratio fields, the base size should be subtracted from the
2598→         * window size prior to checking that the aspect ratio falls in range. If a base size is not provided, nothing
2599→         * should be subtracted from the window size. (The minimum size is not to be used in place of the base size for
2600→         * this purpose.)
2601→         */
2602→         double dx = geometry.width - real_basew;
2603→         double dy = geometry.height - real_baseh;
2604→         double ratio = dx / dy;
2605→         double min = c->size_hints.min_aspect_num / (double) c->size_hints.min_aspect_den;
2606→         double max = c->size_hints.max_aspect_num / (double) c->size_hints.max_aspect_den;
2607→
2608→         if(max > 0 && min > 0 && ratio > 0)
2609→         {
2610→             if(ratio < min)
2611→             {
2612→                 /* dx is lower than allowed, make dy lower to compensate this (+ 0.5 to force proper rounding). */
2613→                 dy = dx / min + 0.5;
2614→                 geometry.width  = (int)(dx + real_basew);
2615→                 geometry.height = (int)(dy + real_baseh);
2616→             } else if(ratio > max)
2617→             {
2618→                 /* dx is too high, lower it (+0.5 for proper rounding) */
2619→                 dx = dy * max + 0.5;
2620→                 geometry.width  = (int)(dx + real_basew);
2621→                 geometry.height = (int)(dy + real_baseh);
2622→             }
2623→         }
2624→    }
2625→
2626→    /* Handle the minimum size */
2627→    geometry.width = MAX(geometry.width, minw);
2628→    geometry.height = MAX(geometry.height, minh);
2629→
2630→    /* Handle the maximum size */
2631→    if(c->size_hints.flags & XCB_ICCCM_SIZE_HINT_P_MAX_SIZE)
2632→    {
2633→        if(c->size_hints.max_width)
